{"command":"cd /workspace/src && cat > u256.rs <<'EOF'
//! A small fixed-width 256-bit unsigned integer.

use std::cmp::Ordering;

#[derive(Clone, Copy, PartialEq, Eq, Default, Debug)]
pub struct U256(pub [u64; 4]); // little-endian limbs

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FromDecStrErr {
    InvalidCharacter,
    InvalidLength,
}

impl std::fmt::Display for FromDecStrErr {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            FromDecStrErr::InvalidCharacter => f.write_str("a character is not in the range 0-9"),
            FromDecStrErr::InvalidLength => f.write_str("the number is too large for the type"),
        }
    }
}

impl U256 {
    pub const ZERO: U256 = U256([0; 4]);

    pub fn from_u64(v: u64) -> U256 {
        U256([v, 0, 0, 0])
    }

    pub fn from_be_bytes(b: &[u8; 32]) -> U256 {
        let mut limbs = [0u64; 4];
        for i in 0..4 {
            let mut w = [0u8; 8];
            w.copy_from_slice(&b[(3 - i) * 8..(3 - i) * 8 + 8]);
            limbs[i] = u64::from_be_bytes(w);
        }
        U256(limbs)
    }

    pub fn to_be_bytes(&self) -> [u8; 32] {
        let mut out = [0u8; 32];
        for i in 0..4 {
            out[(3 - i) * 8..(3 - i) * 8 + 8].copy_from_slice(&self.0[i].to_be_bytes());
        }
        out
    }

    pub fn is_zero(&self) -> bool {
        self.0.iter().all(|&x| x == 0)
    }

    /// Multiplies by a u64, returning the result and the carry out.
    pub fn overflowing_mul_u64(self, m: u64) -> (U256, u64) {
        let mut out = [0u64; 4];
        let mut carry: u128 = 0;
        for i in 0..4 {
            let v = (self.0[i] as u128) * (m as u128) + carry;
            out[i] = v as u64;
            carry = v >> 64;
        }
        (U256(out), carry as u64)
    }

    pub fn overflowing_add(self, o: U256) -> (U256, bool) {
        let mut out = [0u64; 4];
        let mut carry = false;
        for i in 0..4 {
            let (s1, c1) = self.0[i].overflowing_add(o.0[i]);
            let (s2, c2) = s1.overflowing_add(carry as u64);
            out[i] = s2;
            carry = c1 || c2;
        }
        (U256(out), carry)
    }

    pub fn checked_add(self, o: U256) -> Option<U256> {
        let (r, c) = self.overflowing_add(o);
        if c {
            None
        } else {
            Some(r)
        }
    }

    pub fn checked_mul(self, o: U256) -> Option<U256> {
        let mut res = [0u128; 8];
        let mut out = [0u64; 8];
        let _ = &mut res;
        for i in 0..4 {
            let mut carry: u128 = 0;
            for j in 0..4 {
                let cur = out[i + j] as u128 + (self.0[i] as u128) * (o.0[j] as u128) + carry;
                out[i + j] = cur as u64;
                carry = cur >> 64;
            }
            let mut k = i + 4;
            while carry != 0 && k < 8 {
                let cur = out[k] as u128 + carry;
                out[k] = cur as u64;
                carry = cur >> 64;
                k += 1;
            }
        }
        if out[4..].iter().any(|&x| x != 0) {
            None
        } else {
            Some(U256([out[0], out[1], out[2], out[3]]))
        }
    }

    pub fn pow10(n: u32) -> U256 {
        let mut r = U256::from_u64(1);
        for _ in 0..n {
            r = r.overflowing_mul_u64(10).0;
        }
        r
    }

    pub fn not(self) -> U256 {
        U256([!self.0[0], !self.0[1], !self.0[2], !self.0[3]])
    }

    pub fn one_shl(n: u32) -> U256 {
        let mut r = [0u64; 4];
        r[(n / 64) as usize] = 1u64 << (n % 64);
        U256(r)
    }

    pub fn wrapping_sub_one(self) -> U256 {
        let mut out = self.0;
        for i in 0..4 {
            let (v, b) = out[i].overflowing_sub(1);
            out[i] = v;
            if !b {
                break;
            }
        }
        U256(out)
    }

    pub fn from_dec_str(value: &str) -> Result<U256, FromDecStrErr> {
        let mut res = U256::ZERO;
        for b in value.bytes().map(|b| b.wrapping_sub(b'0')) {
            if b > 9 {
                return Err(FromDecStrErr::InvalidCharacter);
            }
            let (r, overflow) = res.overflowing_mul_u64(10);
            if overflow > 0 {
                return Err(FromDecStrErr::InvalidLength);
            }
            let (r, overflow) = r.overflowing_add(U256::from_u64(b as u64));
            if overflow {
                return Err(FromDecStrErr::InvalidLength);
            }
            res = r;
        }
        Ok(res)
    }

    /// Lower hex without leading zeros ("0" for zero).
    pub fn to_hex_lower(&self) -> String {
        if self.is_zero() {
            return "0".to_string();
        }
        let mut s = String::new();
        let mut started = false;
        for i in (0..4).rev() {
            if started {
                s.push_str(&format!("{:016x}", self.0[i]));
            } else if self.0[i] != 0 {
                s.push_str(&format!("{:x}", self.0[i]));
                started = true;
            }
        }
        s
    }
}

impl PartialOrd for U256 {
    fn partial_cmp(&self, other: &U256) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for U256 {
    fn cmp(&self, other: &U256) -> Ordering {
        for i in (0..4).rev() {
            match self.0[i].cmp(&other.0[i]) {
                Ordering::Equal => continue,
                o => return o,
            }
        }
        Ordering::Equal
    }
}
EOF"}

