//! `rustc-hex` (used for fixed hash parsing).

use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum HexError {
    InvalidHexCharacter { c: char, index: usize },
    OddLength,
}

impl fmt::Display for HexError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            HexError::InvalidHexCharacter { c, index } => {
                write!(f, "Invalid character {:?} at position {}", c, index)
            }
            HexError::OddLength => write!(f, "Odd number of digits"),
        }
    }
}

fn val(c: u8, idx: usize) -> Result<u8, HexError> {
    match c {
        b'A'..=b'F' => Ok(c - b'A' + 10),
        b'a'..=b'f' => Ok(c - b'a' + 10),
        b'0'..=b'9' => Ok(c - b'0'),
        _ => Err(HexError::InvalidHexCharacter { c: c as char, index: idx }),
    }
}

pub fn decode(s: &str) -> Result<Vec<u8>, HexError> {
    let b = s.as_bytes();
    if b.len() % 2 != 0 {
        return Err(HexError::OddLength);
    }
    let mut out = Vec::with_capacity(b.len() / 2);
    for (i, pair) in b.chunks(2).enumerate() {
        let hi = val(pair[0], 2 * i)?;
        let lo = val(pair[1], 2 * i + 1)?;
        out.push((hi << 4) | lo);
    }
    Ok(out)
}

pub fn encode(b: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut s = String::with_capacity(b.len() * 2);
    for &x in b {
        s.push(HEX[(x >> 4) as usize] as char);
        s.push(HEX[(x & 0xf) as usize] as char);
    }
    s
}

/// rustc-hex style error.
#[derive(Debug, Clone, PartialEq)]
pub enum RustcHexError {
    InvalidHexCharacter(char, usize),
    InvalidHexLength,
}

impl fmt::Display for RustcHexError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            RustcHexError::InvalidHexCharacter(ch, idx) => {
                write!(f, "Invalid character '{}' at position {}", ch, idx)
            }
            RustcHexError::InvalidHexLength => write!(f, "Invalid input length"),
        }
    }
}

/// Parses a 32 byte hash the way `fixed-hash`'s `FromStr` does.
pub fn parse_h256(input: &str) -> Result<[u8; 32], RustcHexError> {
    let input = input.strip_prefix("0x").unwrap_or(input);
    let bytes = input.as_bytes();
    let mut pos = 0usize;
    // iterator returning next byte
    let mut next = |pos: &mut usize| -> Option<Result<u8, RustcHexError>> {
        let mut modulus = 0;
        let mut buf: u8 = 0;
        while *pos < bytes.len() {
            let index = *pos;
            let byte = bytes[index];
            *pos += 1;
            buf <<= 4;
            match byte {
                b'A'..=b'F' => buf |= byte - b'A' + 10,
                b'a'..=b'f' => buf |= byte - b'a' + 10,
                b'0'..=b'9' => buf |= byte - b'0',
                b' ' | b'\r' | b'\n' | b'\t' => {
                    buf >>= 4;
                    continue;
                }
                _ => {
                    let ch = input[index..].chars().next().unwrap_or('\u{fffd}');
                    return Some(Err(RustcHexError::InvalidHexCharacter(ch, index)));
                }
            }
            modulus += 1;
            if modulus == 2 {
                return Some(Ok(buf));
            }
        }
        if modulus != 0 {
            Some(Err(RustcHexError::InvalidHexLength))
        } else {
            None
        }
    };
    let mut out = [0u8; 32];
    for i in 0..32 {
        match next(&mut pos) {
            None => return Err(RustcHexError::InvalidHexLength),
            Some(Err(e)) => return Err(e),
            Some(Ok(b)) => out[i] = b,
        }
    }
    if next(&mut pos).is_some() {
        return Err(RustcHexError::InvalidHexLength);
    }
    Ok(out)
}

/// Display of an H256 the way fixed-hash does it: `0xabcd…ef01`.
pub fn h256_short(h: &[u8; 32]) -> String {
    format!(
        "0x{:02x}{:02x}\u{2026}{:02x}{:02x}",
        h[0], h[1], h[30], h[31]
    )
}
EOF"}

