//! ABI parameter types, their textual representation and the type reader.

use crate::panics::{slice, Site};
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParamType {
    Address,
    Bytes,
    Int(usize),
    Uint(usize),
    Bool,
    String,
    Array(Box<ParamType>),
    FixedBytes(usize),
    FixedArray(Box<ParamType>, usize),
    Tuple(Vec<ParamType>),
}

impl fmt::Display for ParamType {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.write_str(&write_type(self))
    }
}

pub fn write_type(p: &ParamType) -> String {
    match p {
        ParamType::Address => "address".to_owned(),
        ParamType::Bytes => "bytes".to_owned(),
        ParamType::FixedBytes(len) => format!("bytes{}", len),
        ParamType::Int(len) => format!("int{}", len),
        ParamType::Uint(len) => format!("uint{}", len),
        ParamType::Bool => "bool".to_owned(),
        ParamType::String => "string".to_owned(),
        ParamType::FixedArray(inner, len) => format!("{}[{}]", write_type(inner), len),
        ParamType::Array(inner) => format!("{}[]", write_type(inner)),
        ParamType::Tuple(items) => {
            let parts: Vec<String> = items.iter().map(write_type).collect();
            format!("({})", parts.join(","))
        }
    }
}

impl ParamType {
    pub fn is_dynamic(&self) -> bool {
        match self {
            ParamType::Bytes | ParamType::String | ParamType::Array(_) => true,
            ParamType::FixedArray(elem, _) => elem.is_dynamic(),
            ParamType::Tuple(params) => params.iter().any(|p| p.is_dynamic()),
            _ => false,
        }
    }

    pub fn is_empty_bytes_valid_encoding(&self) -> bool {
        match self {
            ParamType::FixedBytes(len) => *len == 0,
            ParamType::FixedArray(_, len) => *len == 0,
            _ => false,
        }
    }
}

/// Errors that can be produced while reading a type.
#[derive(Debug, Clone)]
pub enum ReadError {
    InvalidName(String),
    ParseInt(ParseIntError),
}

fn parse_usize(s: &str) -> Result<usize, ReadError> {
    usize::from_str_radix(s, 10).map_err(ReadError::ParseInt)
}

pub fn read(name: &str) -> Result<ParamType, ReadError> {
    match name.chars().last() {
        // check if it is a struct
        Some(')') => {
            if !name.starts_with('(') {
                return Err(ReadError::InvalidName(name.to_owned()));
            }

            let mut subtypes: Vec<ParamType> = Vec::new();
            let mut subtuples: Vec<Vec<ParamType>> = Vec::new();
            let mut nested = 0isize;
            let mut top_level_paren_open = 0usize;
            let mut last_item = 1usize;

            let chars: Vec<char> = name.chars().collect();
            let mut idx = 0usize;
            while idx < chars.len() {
                let mut pos = idx;
                let c = chars[idx];
                idx += 1;
                match c {
                    '(' => {
                        top_level_paren_open = pos;
                        nested += 1;
                        if nested > 1 {
                            subtuples.push(vec![]);
                            last_item = pos + 1;
                        }
                    }
                    ')' => {
                        nested -= 1;
                        if nested < 0 {
                            return Err(ReadError::InvalidName(name.to_owned()));
                        } else if slice(name, last_item, pos, Site::ReaderCloseEmpty).is_empty() {
                            last_item = pos + 1;
                        } else if nested == 0 {
                            let sub = slice(name, last_item, pos, Site::ReaderCloseTop);
                            let subtype = read(sub)?;
                            subtypes.push(subtype);
                            last_item = pos + 1;
                        } else if nested > 0 {
                            loop {
                                match chars.get(idx) {
                                    Some(',') | Some(')') | None => break,
                                    _ => {
                                        idx += 1;
                                        pos += 1;
                                    }
                                }
                            }
                            let inner_tuple =
                                slice(name, top_level_paren_open, pos + 1, Site::ReaderInnerTuple);
                            let subtype = read(inner_tuple)?;
                            if nested > 1 {
                                let k = (nested - 2) as usize;
                                let mut subtuple = std::mem::take(&mut subtuples[k]);
                                subtuple.push(subtype);
                                subtypes.push(ParamType::Tuple(subtuple));
                            } else {
                                subtypes.push(subtype);
                            }
                            last_item = pos + 1;
                        }
                    }
                    ',' => {
                        if slice(name, last_item, pos, Site::ReaderCommaEmpty).is_empty() {
                            last_item = pos + 1
                        } else if nested == 1 {
                            let sub = slice(name, last_item, pos, Site::ReaderCommaTop);
                            let subtype = read(sub)?;
                            subtypes.push(subtype);
                            last_item = pos + 1;
                        } else if nested > 1 {
                            let sub = slice(name, last_item, pos, Site::ReaderCommaNested);
                            let subtype = read(sub)?;
                            let k = (nested - 2) as usize;
                            subtuples[k].push(subtype);
                            last_item = pos + 1;
                        }
                    }
                    _ => (),
                }
            }
            return Ok(ParamType::Tuple(subtypes));
        }
        // check if it is a fixed or dynamic array.
        Some(']') => {
            // take number part
            let num: String = name
                .chars()
                .rev()
                .skip(1)
                .take_while(|c| *c != '[')
                .collect::<String>()
                .chars()
                .rev()
                .collect();

            let count = name.chars().count();
            return if num.is_empty() {
                // we already know it's a dynamic array!
                let subtype = read(slice(name, 0, count.wrapping_sub(2), Site::ReaderArrayDyn))?;
                Ok(ParamType::Array(Box::new(subtype)))
            } else {
                // it's a fixed array.
                let len = parse_usize(&num)?;
                let end = count.wrapping_sub(num.len()).wrapping_sub(2);
                let subtype = read(slice(name, 0, end, Site::ReaderArrayFixed))?;
                Ok(ParamType::FixedArray(Box::new(subtype), len))
            };
        }
        _ => (),
    }

    let result = match name {
        "address" => ParamType::Address,
        "bytes" => ParamType::Bytes,
        "bool" => ParamType::Bool,
        "string" => ParamType::String,
        "int" => ParamType::Int(256),
        "tuple" => ParamType::Tuple(vec![]),
        "uint" => ParamType::Uint(256),
        s if s.starts_with("int") => {
            let len = parse_usize(&s[3..])?;
            ParamType::Int(len)
        }
        s if s.starts_with("uint") => {
            let len = parse_usize(&s[4..])?;
            ParamType::Uint(len)
        }
        s if s.starts_with("bytes") => {
            let len = parse_usize(&s[5..])?;
            ParamType::FixedBytes(len)
        }
        _ => ParamType::Uint(8),
    };

    Ok(result)
}
EOF"}

