//! Error types and their textual rendering.

use crate::hexutil::{HexError, RustcHexError};
use crate::json::JsonError;
use crate::paramtype::ReadError;
use crate::u256::FromDecStrErr;
use std::num::ParseIntError;

/// Mirrors the error enum of the ABI library.
#[derive(Debug, Clone)]
pub enum AbiError {
    InvalidName(String),
    InvalidData,
    SerdeJson(JsonError),
    ParseInt(ParseIntError),
    Hex(HexError),
    Other(String),
    UintParse(FromDecStrErr),
}

impl From<ReadError> for AbiError {
    fn from(e: ReadError) -> AbiError {
        match e {
            ReadError::InvalidName(s) => AbiError::InvalidName(s),
            ReadError::ParseInt(p) => AbiError::ParseInt(p),
        }
    }
}

impl From<HexError> for AbiError {
    fn from(e: HexError) -> AbiError {
        AbiError::Hex(e)
    }
}

impl From<FromDecStrErr> for AbiError {
    fn from(e: FromDecStrErr) -> AbiError {
        AbiError::UintParse(e)
    }
}

/// The top level error printed by `main`.
#[derive(Debug, Clone)]
pub struct AppError {
    pub msg: String,
    pub causes: Vec<String>,
}

impl AppError {
    pub fn msg<S: Into<String>>(s: S) -> AppError {
        AppError { msg: s.into(), causes: vec![] }
    }

    pub fn render(&self) -> String {
        let mut out = format!("Error: {}", self.msg);
        if !self.causes.is_empty() {
            out.push_str("\n\nCaused by:");
            if self.causes.len() == 1 {
                out.push_str(&format!("\n    {}", self.causes[0]));
            } else {
                for (i, c) in self.causes.iter().enumerate() {
                    out.push_str(&format!("\n    {}: {}", i, c));
                }
            }
        }
        out
    }
}

impl From<AbiError> for AppError {
    fn from(e: AbiError) -> AppError {
        match e {
            AbiError::InvalidName(s) => AppError::msg(format!("Invalid name: {}", s)),
            AbiError::InvalidData => AppError::msg("Invalid data"),
            AbiError::SerdeJson(j) => {
                let s = j.to_string();
                AppError { msg: format!("Serialization error: {}", s), causes: vec![s] }
            }
            AbiError::ParseInt(p) => {
                let s = p.to_string();
                AppError { msg: format!("Integer parsing error: {}", s), causes: vec![s] }
            }
            AbiError::Hex(h) => {
                let s = h.to_string();
                AppError { msg: format!("Hex parsing error: {}", s), causes: vec![s] }
            }
            AbiError::Other(s) => AppError::msg(s),
            AbiError::UintParse(u) => AppError::msg(format!("Uint parse error: {:?}", u)),
        }
    }
}

impl From<ReadError> for AppError {
    fn from(e: ReadError) -> AppError {
        AppError::from(AbiError::from(e))
    }
}

impl From<HexError> for AppError {
    fn from(e: HexError) -> AppError {
        AppError::msg(e.to_string())
    }
}

impl From<RustcHexError> for AppError {
    fn from(e: RustcHexError) -> AppError {
        AppError::msg(e.to_string())
    }
}

impl From<std::io::Error> for AppError {
    fn from(e: std::io::Error) -> AppError {
        AppError::msg(e.to_string())
    }
}
EOF"}

