//! ABI tokens and the textual tokenizers (strict and lenient).

use crate::errors::AbiError;
use crate::hexutil;
use crate::panics::{slice, Site};
use crate::paramtype::ParamType;
use crate::u256::U256;
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Address([u8; 20]),
    FixedBytes(Vec<u8>),
    Bytes(Vec<u8>),
    Int(U256),
    Uint(U256),
    Bool(bool),
    String(String),
    FixedArray(Vec<Token>),
    Array(Vec<Token>),
    Tuple(Vec<Token>),
}

impl fmt::Display for Token {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Token::Bool(b) => write!(f, "{}", b),
            Token::String(s) => write!(f, "{}", s),
            Token::Address(a) => write!(f, "{}", hexutil::encode(a)),
            Token::Bytes(b) | Token::FixedBytes(b) => write!(f, "{}", hexutil::encode(b)),
            Token::Uint(i) | Token::Int(i) => write!(f, "{}", i.to_hex_lower()),
            Token::Array(arr) | Token::FixedArray(arr) => {
                let s: Vec<String> = arr.iter().map(|t| t.to_string()).collect();
                write!(f, "[{}]", s.join(","))
            }
            Token::Tuple(arr) => {
                let s: Vec<String> = arr.iter().map(|t| t.to_string()).collect();
                write!(f, "({})", s.join(","))
            }
        }
    }
}

impl Token {
    pub fn is_dynamic(&self) -> bool {
        match self {
            Token::Bytes(_) | Token::String(_) | Token::Array(_) => true,
            Token::FixedArray(tokens) => tokens.iter().any(|t| t.is_dynamic()),
            Token::Tuple(tokens) => tokens.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }

    pub fn type_check(&self, param_type: &ParamType) -> bool {
        match self {
            Token::Address(_) => *param_type == ParamType::Address,
            Token::Bytes(_) => *param_type == ParamType::Bytes,
            Token::Int(_) => matches!(param_type, ParamType::Int(_)),
            Token::Uint(_) => matches!(param_type, ParamType::Uint(_)),
            Token::Bool(_) => *param_type == ParamType::Bool,
            Token::String(_) => *param_type == ParamType::String,
            Token::FixedBytes(bytes) => {
                if let ParamType::FixedBytes(size) = param_type {
                    *size >= bytes.len()
                } else {
                    false
                }
            }
            Token::Array(tokens) => {
                if let ParamType::Array(inner) = param_type {
                    tokens.iter().all(|t| t.type_check(inner))
                } else {
                    false
                }
            }
            Token::FixedArray(tokens) => {
                if let ParamType::FixedArray(inner, size) = param_type {
                    *size == tokens.len() && tokens.iter().all(|t| t.type_check(inner))
                } else {
                    false
                }
            }
            Token::Tuple(tokens) => {
                if let ParamType::Tuple(inner) = param_type {
                    tokens.iter().enumerate().all(|(i, t)| match inner.get(i) {
                        Some(p) => t.type_check(p),
                        None => {
                            panic!(
                                "index out of bounds: the len is {} but the index is {}",
                                inner.len(),
                                i
                            )
                        }
                    })
                } else {
                    false
                }
            }
        }
    }

    pub fn types_check(tokens: &[Token], param_types: &[ParamType]) -> bool {
        param_types.len() == tokens.len()
            && param_types.iter().zip(tokens).all(|(p, t)| t.type_check(p))
    }
}

fn strip0x(s: &str) -> &str {
    s.strip_prefix("0x").unwrap_or(s)
}

pub struct Tokenizer {
    pub lenient: bool,
}

impl Tokenizer {
    pub fn tokenize(&self, param: &ParamType, value: &str) -> Result<Token, AbiError> {
        match param {
            ParamType::Address => self.tokenize_address(strip0x(value)).map(Token::Address),
            ParamType::String => Ok(Token::String(value.to_owned())),
            ParamType::Bool => self.tokenize_bool(value).map(Token::Bool),
            ParamType::Bytes => self.tokenize_bytes(strip0x(value)).map(Token::Bytes),
            ParamType::FixedBytes(len) => {
                self.tokenize_fixed_bytes(strip0x(value), *len).map(Token::FixedBytes)
            }
            ParamType::Uint(_) => self.tokenize_uint(value).map(|b| Token::Uint(U256::from_be_bytes(&b))),
            ParamType::Int(_) => self.tokenize_int(value).map(|b| Token::Int(U256::from_be_bytes(&b))),
            ParamType::Array(p) => self.tokenize_array(value, p).map(Token::Array),
            ParamType::FixedArray(p, len) => {
                self.tokenize_fixed_array(value, p, *len).map(Token::FixedArray)
            }
            ParamType::Tuple(p) => self.tokenize_struct(value, p).map(Token::Tuple),
        }
    }

    fn tokenize_address(&self, value: &str) -> Result<[u8; 20], AbiError> {
        let hex = hexutil::decode(value)?;
        if hex.len() == 20 {
            let mut a = [0u8; 20];
            a.copy_from_slice(&hex);
            Ok(a)
        } else {
            Err(AbiError::InvalidData)
        }
    }

    fn tokenize_bool(&self, value: &str) -> Result<bool, AbiError> {
        match value {
            "true" | "1" => Ok(true),
            "false" | "0" => Ok(false),
            _ => Err(AbiError::InvalidData),
        }
    }

    fn tokenize_bytes(&self, value: &str) -> Result<Vec<u8>, AbiError> {
        Ok(hexutil::decode(value)?)
    }

    fn tokenize_fixed_bytes(&self, value: &str, len: usize) -> Result<Vec<u8>, AbiError> {
        let hex = hexutil::decode(value)?;
        if hex.len() == len {
            Ok(hex)
        } else {
            Err(AbiError::InvalidData)
        }
    }

    fn strict_uint(value: &str) -> Result<[u8; 32], AbiError> {
        let hex = hexutil::decode(value)?;
        if hex.len() == 32 {
            let mut out = [0u8; 32];
            out.copy_from_slice(&hex);
            Ok(out)
        } else {
            Err(AbiError::InvalidData)
        }
    }

    fn tokenize_uint(&self, value: &str) -> Result<[u8; 32], AbiError> {
        let result = Self::strict_uint(value);
        if !self.lenient || result.is_ok() {
            return result;
        }
        let uint = match U256::from_dec_str(value) {
            Ok(u) => u,
            Err(dec_error) => {
                let original_dec_error = dec_error.to_string();
                match parse_units(value) {
                    Some((integer, fract, units)) => {
                        let units: u32 = match units {
                            "ether" => 18,
                            "gwei" | "nano" | "nanoether" => 9,
                            "wei" => 0,
                            _ => return Err(dec_error.into()),
                        };
                        let integer =
                            U256::from_dec_str(integer)?.checked_mul(U256::pow10(units));
                        if fract.is_empty() {
                            integer.ok_or(AbiError::UintParse(dec_error))?
                        } else {
                            let fract_pow = match (units as usize).checked_sub(fract.chars().count_bytes_hack(fract)) {
                                Some(p) => p,
                                None => return Err(AbiError::UintParse(dec_error)),
                            };
                            let fract = U256::from_dec_str(fract)?
                                .checked_mul(U256::pow10(fract_pow as u32))
                                .ok_or_else(|| AbiError::Other(original_dec_error.clone()))?;
                            integer
                                .and_then(|i| i.checked_add(fract))
                                .ok_or(AbiError::Other(original_dec_error))?
                        }
                    }
                    None => return Err(dec_error.into()),
                }
            }
        };
        Ok(uint.to_be_bytes())
    }

    fn tokenize_int(&self, value: &str) -> Result<[u8; 32], AbiError> {
        let result = Self::strict_uint(value);
        if !self.lenient || result.is_ok() {
            return result;
        }
        let abs = U256::from_dec_str(value.trim_start_matches('-'))?;
        let neg = value.starts_with('-');
        let max = if neg {
            U256::one_shl(255)
        } else {
            U256::one_shl(255).wrapping_sub_one()
        };
        if abs > max {
            return Err(AbiError::Other(
                if neg { "int256 parse error: Underflow" } else { "int256 parse error: Overflow" }
                    .to_string(),
            ));
        }
        let int = if neg { abs.not().overflowing_add(U256::from_u64(1)).0 } else { abs };
        Ok(int.to_be_bytes())
    }

    fn tokenize_fixed_array(
        &self,
        value: &str,
        param: &ParamType,
        len: usize,
    ) -> Result<Vec<Token>, AbiError> {
        let result = self.tokenize_array(value, param)?;
        if result.len() == len {
            Ok(result)
        } else {
            Err(AbiError::InvalidData)
        }
    }

    fn tokenize_struct(&self, value: &str, params: &[ParamType]) -> Result<Vec<Token>, AbiError> {
        if !value.starts_with('(') || !value.ends_with(')') {
            return Err(AbiError::InvalidData);
        }
        if value.chars().count() == 2 {
            return Ok(vec![]);
        }
        let mut result = vec![];
        let mut nested = 0isize;
        let mut ignore = false;
        let mut last_item = 1usize;
        let mut params = params.iter();
        for (pos, ch) in value.chars().enumerate() {
            match ch {
                '(' | '[' if !ignore => {
                    nested += 1;
                }
                ')' | ']' if !ignore => {
                    nested -= 1;
                    if nested < 0 {
                        return Err(AbiError::InvalidData);
                    } else if nested == 0 {
                        let sub = slice(value, last_item, pos, Site::StructClose);
                        let p = params.next().ok_or(AbiError::InvalidData)?;
                        let token = self.tokenize(p, sub)?;
                        result.push(token);
                        last_item = pos + 1;
                    }
                }
                '"' => {
                    ignore = !ignore;
                }
                ',' if nested == 1 && !ignore => {
                    let sub = slice(value, last_item, pos, Site::StructComma);
                    let p = params.next().ok_or(AbiError::InvalidData)?;
                    let token = self.tokenize(p, sub)?;
                    result.push(token);
                    last_item = pos + 1;
                }
                _ => (),
            }
        }
        if ignore {
            return Err(AbiError::InvalidData);
        }
        Ok(result)
    }

    fn tokenize_array(&self, value: &str, param: &ParamType) -> Result<Vec<Token>, AbiError> {
        if !value.starts_with('[') || !value.ends_with(']') {
            return Err(AbiError::InvalidData);
        }
        if value.chars().count() == 2 {
            return Ok(vec![]);
        }
        let mut result = vec![];
        let mut nested = 0isize;
        let mut ignore = false;
        let mut last_item = 1usize;

        let mut tuple_nested = 0isize;
        let mut tuple_item_start = 1usize;
        let mut last_is_tuple = false;
        for (i, ch) in value.chars().enumerate() {
            match ch {
                '(' if !ignore => {
                    if tuple_nested == 0 {
                        tuple_item_start = i;
                    }
                    tuple_nested += 1;
                }
                ')' if !ignore => {
                    tuple_nested -= 1;
                    if tuple_nested < 0 {
                        return Err(AbiError::InvalidData);
                    } else if tuple_nested == 0 {
                        let sub = slice(value, tuple_item_start, i + 1, Site::ArrayTupleClose);
                        let token = self.tokenize(param, sub)?;
                        result.push(token);
                        last_is_tuple = !last_is_tuple;
                    }
                }
                _ if tuple_nested != 0 => {}
                '[' if !ignore => {
                    nested += 1;
                }
                ']' if !ignore => {
                    nested -= 1;
                    if nested < 0 {
                        return Err(AbiError::InvalidData);
                    } else if nested == 0 {
                        if last_is_tuple {
                            last_is_tuple = !last_is_tuple;
                        } else {
                            let sub = slice(value, last_item, i, Site::ArrayClose);
                            let token = self.tokenize(param, sub)?;
                            result.push(token);
                            last_item = i + 1;
                        }
                    }
                }
                '"' => {
                    ignore = !ignore;
                }
                ',' if nested == 1 && !ignore => {
                    if last_is_tuple {
                        last_is_tuple = !last_is_tuple;
                    } else {
                        let sub = slice(value, last_item, i, Site::ArrayComma);
                        let token = self.tokenize(param, sub)?;
                        result.push(token);
                    }
                    last_item = i + 1;
                }
                _ => (),
            }
        }
        if ignore {
            return Err(AbiError::InvalidData);
        }
        Ok(result)
    }
}

trait CountHack {
    fn count_bytes_hack(self, s: &str) -> usize;
}

impl<I: Iterator<Item = char>> CountHack for I {
    fn count_bytes_hack(self, s: &str) -> usize {
        s.len()
    }
}

fn is_unicode_digit(c: char) -> bool {
    crate::unicode::is_decimal_digit(c)
}

fn is_unicode_space(c: char) -> bool {
    c.is_whitespace()
}

/// Emulates the regex `^(?P<integer>\d+)(\.(?P<fract>\d+))?\s*(?P<units>(ether|gwei|nanoether|nano|wei))$`.
fn parse_units(value: &str) -> Option<(&str, &str, &str)> {
    let chars: Vec<(usize, char)> = value.char_indices().collect();
    let n = chars.len();
    let byte_at = |i: usize| if i < n { chars[i].0 } else { value.len() };
