        let start = i + 1;
        let mut j = start;
        while j < n && is_unicode_digit(chars[j].1) {
            j += 1;
        }
        if j > start {
            fract = &value[byte_at(start)..byte_at(j)];
            i = j;
        }
    }
    while i < n && is_unicode_space(chars[i].1) {
        i += 1;
    }
    let rest = &value[byte_at(i)..];
    match rest {
        "ether" | "gwei" | "nanoether" | "nano" | "wei" => Some((integer, fract, rest)),
        _ => None,
    }
