//! ABI encoding and decoding.

use crate::errors::AbiError;
use crate::paramtype::ParamType;
use crate::token::Token;
use crate::u256::U256;

type Word = [u8; 32];

fn pad_u32(v: u32) -> Word {
    let mut w = [0u8; 32];
    w[28..].copy_from_slice(&v.to_be_bytes());
    w
}

fn pad_bytes_len(bytes: &[u8]) -> u32 {
    ((bytes.len() + 31) / 32) as u32 + 1
}

fn fixed_bytes_len(bytes: &[u8]) -> u32 {
    ((bytes.len() + 31) / 32) as u32
}

fn fixed_bytes_append(result: &mut Vec<Word>, bytes: &[u8]) {
    let len = (bytes.len() + 31) / 32;
    for i in 0..len {
        let mut padded = [0u8; 32];
        let to_copy = if i == len - 1 {
            match bytes.len() % 32 {
                0 => 32,
                x => x,
            }
        } else {
            32
        };
        let offset = 32 * i;
        padded[..to_copy].copy_from_slice(&bytes[offset..offset + to_copy]);
        result.push(padded);
    }
}

fn pad_bytes_append(data: &mut Vec<Word>, bytes: &[u8]) {
    data.push(pad_u32(bytes.len() as u32));
    fixed_bytes_append(data, bytes);
}

enum Mediate<'a> {
    Raw(u32, &'a Token),
    RawArray(Vec<Mediate<'a>>),
    Prefixed(u32, &'a Token),
    PrefixedArray(Vec<Mediate<'a>>),
    PrefixedArrayWithLength(Vec<Mediate<'a>>),
}

impl<'a> Mediate<'a> {
    fn head_len(&self) -> u32 {
        match self {
            Mediate::Raw(len, _) => 32u32.wrapping_mul(*len),
            Mediate::RawArray(m) => m.iter().map(|x| x.head_len()).fold(0u32, |a, b| a.wrapping_add(b)),
            Mediate::Prefixed(..) | Mediate::PrefixedArray(_) | Mediate::PrefixedArrayWithLength(_) => 32,
        }
    }

    fn tail_len(&self) -> u32 {
        match self {
            Mediate::Raw(..) | Mediate::RawArray(_) => 0,
            Mediate::Prefixed(len, _) => 32u32.wrapping_mul(*len),
            Mediate::PrefixedArray(m) => m
                .iter()
                .fold(0u32, |acc, x| acc.wrapping_add(x.head_len()).wrapping_add(x.tail_len())),
            Mediate::PrefixedArrayWithLength(m) => m
                .iter()
                .fold(32u32, |acc, x| acc.wrapping_add(x.head_len()).wrapping_add(x.tail_len())),
        }
    }

    fn head_append(&self, acc: &mut Vec<Word>, suffix_offset: u32) {
        match self {
            Mediate::Raw(_, raw) => encode_token_append(acc, raw),
            Mediate::RawArray(raw) => raw.iter().for_each(|m| m.head_append(acc, 0)),
            Mediate::Prefixed(..) | Mediate::PrefixedArray(_) | Mediate::PrefixedArrayWithLength(_) => {
                acc.push(pad_u32(suffix_offset))
            }
        }
    }

    fn tail_append(&self, acc: &mut Vec<Word>) {
        match self {
            Mediate::Raw(..) | Mediate::RawArray(_) => {}
            Mediate::Prefixed(_, raw) => encode_token_append(acc, raw),
            Mediate::PrefixedArray(m) => encode_head_tail_append(acc, m),
            Mediate::PrefixedArrayWithLength(m) => {
                acc.push(pad_u32(m.len() as u32));
                encode_head_tail_append(acc, m);
            }
        }
    }
}

fn encode_head_tail_append(acc: &mut Vec<Word>, mediates: &[Mediate]) {
    let heads_len = mediates.iter().fold(0u32, |a, m| a.wrapping_add(m.head_len()));
    let mut offset = heads_len;
    for m in mediates {
        m.head_append(acc, offset);
        offset = offset.wrapping_add(m.tail_len());
    }
    mediates.iter().for_each(|m| m.tail_append(acc));
}

fn mediate_token(token: &Token) -> Mediate {
    match token {
        Token::Address(_) => Mediate::Raw(1, token),
        Token::Bytes(b) => Mediate::Prefixed(pad_bytes_len(b), token),
        Token::String(s) => Mediate::Prefixed(pad_bytes_len(s.as_bytes()), token),
        Token::FixedBytes(b) => Mediate::Raw(fixed_bytes_len(b), token),
        Token::Int(_) | Token::Uint(_) | Token::Bool(_) => Mediate::Raw(1, token),
        Token::Array(tokens) => {
            Mediate::PrefixedArrayWithLength(tokens.iter().map(mediate_token).collect())
        }
        Token::FixedArray(tokens) | Token::Tuple(tokens) => {
            let m = tokens.iter().map(mediate_token).collect();
            if token.is_dynamic() {
                Mediate::PrefixedArray(m)
            } else {
                Mediate::RawArray(m)
            }
        }
    }
}

fn encode_token_append(data: &mut Vec<Word>, token: &Token) {
    match token {
        Token::Address(a) => {
            let mut padded = [0u8; 32];
            padded[12..].copy_from_slice(a);
            data.push(padded);
        }
        Token::Bytes(b) => pad_bytes_append(data, b),
        Token::String(s) => pad_bytes_append(data, s.as_bytes()),
        Token::FixedBytes(b) => fixed_bytes_append(data, b),
        Token::Int(i) | Token::Uint(i) => data.push(i.to_be_bytes()),
        Token::Bool(b) => {
            let mut v = [0u8; 32];
            if *b {
                v[31] = 1;
            }
            data.push(v);
        }
        _ => panic!("Unhandled nested token: {:?}", token),
    }
}

pub fn encode(tokens: &[Token]) -> Vec<u8> {
    let mediates: Vec<Mediate> = tokens.iter().map(mediate_token).collect();
    let mut result = Vec::new();
    encode_head_tail_append(&mut result, &mediates);
    result.into_iter().flat_map(|w| w.into_iter()).collect()
}

// ---------------------------------------------------------------- decoding

struct DecodeResult {
    token: Token,
    new_offset: usize,
}

fn peek(data: &[u8], offset: usize, len: usize) -> Result<&[u8], AbiError> {
    match offset.checked_add(len) {
        Some(end) if end <= data.len() => Ok(&data[offset..end]),
        _ => Err(AbiError::InvalidData),
    }
}

fn peek_32_bytes(data: &[u8], offset: usize) -> Result<Word, AbiError> {
    peek(data, offset, 32).map(|x| {
        let mut out = [0u8; 32];
        out.copy_from_slice(&x[0..32]);
        out
    })
}

fn take_bytes(data: &[u8], offset: usize, len: usize) -> Result<Vec<u8>, AbiError> {
    match offset.checked_add(len) {
        Some(end) if end <= data.len() => Ok(data[offset..end].to_vec()),
        _ => Err(AbiError::InvalidData),
    }
}

fn check_zeroes(data: &[u8]) -> bool {
    data.iter().all(|b| *b == 0)
}

fn as_usize(slice: &Word) -> Result<usize, AbiError> {
    if !check_zeroes(&slice[..28]) {
        return Err(AbiError::InvalidData);
    }
    let result = ((slice[28] as usize) << 24)
        + ((slice[29] as usize) << 16)
        + ((slice[30] as usize) << 8)
        + (slice[31] as usize);
    Ok(result)
}

fn as_bool(slice: &Word) -> Result<bool, AbiError> {
    if !check_zeroes(&slice[..31]) {
        return Err(AbiError::InvalidData);
    }
    Ok(slice[31] == 1)
}

fn add_checked(a: usize, b: usize) -> Result<usize, AbiError> {
