//! A JSON reader reproducing the behaviour (including error messages and
//! positions) of a streaming JSON deserializer reading from an `io::Read`.

use std::fmt;

#[derive(Debug, Clone)]
pub struct JsonError {
    pub msg: String,
    pub line: usize,
    pub column: usize,
}

impl JsonError {
    pub fn custom<S: Into<String>>(s: S) -> JsonError {
        JsonError { msg: s.into(), line: 0, column: 0 }
    }

    pub fn io(e: &std::io::Error) -> JsonError {
        JsonError { msg: e.to_string(), line: 0, column: 0 }
    }

    pub fn has_position(&self) -> bool {
        self.line != 0
    }
}

impl fmt::Display for JsonError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        if self.line == 0 {
            f.write_str(&self.msg)
        } else {
            write!(f, "{} at line {} column {}", self.msg, self.line, self.column)
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub enum Code {
    EofWhileParsingList,
    EofWhileParsingObject,
    EofWhileParsingString,
    EofWhileParsingValue,
    ExpectedColon,
    ExpectedListCommaOrEnd,
    ExpectedObjectCommaOrEnd,
    ExpectedSomeIdent,
    ExpectedSomeValue,
    InvalidEscape,
    InvalidNumber,
    NumberOutOfRange,
    InvalidUnicodeCodePoint,
    ControlCharacterWhileParsingString,
    KeyMustBeAString,
    LoneLeadingSurrogateInHexEscape,
    TrailingComma,
    TrailingCharacters,
    UnexpectedEndOfHexEscape,
    RecursionLimitExceeded,
}

impl Code {
    fn message(self) -> &'static str {
        match self {
            Code::EofWhileParsingList => "EOF while parsing a list",
            Code::EofWhileParsingObject => "EOF while parsing an object",
            Code::EofWhileParsingString => "EOF while parsing a string",
            Code::EofWhileParsingValue => "EOF while parsing a value",
            Code::ExpectedColon => "expected `:`",
            Code::ExpectedListCommaOrEnd => "expected `,` or `]`",
            Code::ExpectedObjectCommaOrEnd => "expected `,` or `}`",
            Code::ExpectedSomeIdent => "expected ident",
            Code::ExpectedSomeValue => "expected value",
            Code::InvalidEscape => "invalid escape",
            Code::InvalidNumber => "invalid number",
            Code::NumberOutOfRange => "number out of range",
            Code::InvalidUnicodeCodePoint => "invalid unicode code point",
            Code::ControlCharacterWhileParsingString => {
                "control character (\\u0000-\\u001F) found while parsing a string"
            }
            Code::KeyMustBeAString => "key must be a string",
            Code::LoneLeadingSurrogateInHexEscape => "lone leading surrogate in hex escape",
            Code::TrailingComma => "trailing comma",
            Code::TrailingCharacters => "trailing characters",
            Code::UnexpectedEndOfHexEscape => "unexpected end of hex escape",
            Code::RecursionLimitExceeded => "recursion limit exceeded",
        }
    }
}

/// Buffered generic JSON value.
#[derive(Debug, Clone)]
pub enum Content {
    Bool(bool),
    U64(u64),
    I64(i64),
    F64(f64),
    String(String),
    Unit,
    Seq(Vec<Content>),
    Map(Vec<(Content, Content)>),
}

/// What kind of value was found, for "invalid type" messages.
#[derive(Debug, Clone)]
pub enum Unexpected {
    Bool(bool),
    Unsigned(u64),
    Signed(i64),
    Float(f64),
    Str(String),
    Unit,
    Seq,
    Map,
}

impl Content {
    pub fn unexpected(&self) -> Unexpected {
        match self {
            Content::Bool(b) => Unexpected::Bool(*b),
            Content::U64(n) => Unexpected::Unsigned(*n),
            Content::I64(n) => Unexpected::Signed(*n),
            Content::F64(f) => Unexpected::Float(*f),
            Content::String(s) => Unexpected::Str(s.clone()),
            Content::Unit => Unexpected::Unit,
            Content::Seq(_) => Unexpected::Seq,
            Content::Map(_) => Unexpected::Map,
        }
    }
}

pub fn format_float(v: f64) -> String {
    if v == 0.0 {
        return if v.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    if !v.is_finite() {
        return format!("{}", v);
    }
    let e = format!("{:e}", v);
    let (neg, rest) = match e.strip_prefix('-') {
        Some(r) => (true, r),
        None => (false, e.as_str()),
    };
    let (mant, exp) = rest.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let length = digits.len() as i32;
    let kk = exp + 1;
    let k = kk - length;
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if 0 <= k && kk <= 16 {
        out.push_str(&digits);
        for _ in 0..k {
            out.push('0');
        }
        out.push_str(".0");
    } else if 0 < kk && kk <= 16 {
        out.push_str(&digits[..kk as usize]);
        out.push('.');
        out.push_str(&digits[kk as usize..]);
    } else if -5 < kk && kk <= 0 {
        out.push_str("0.");
        for _ in 0..(-kk) {
            out.push('0');
        }
        out.push_str(&digits);
    } else {
        out.push_str(&digits[..1]);
        if length > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        let x = kk - 1;
        if x >= 0 {
            out.push('+');
        }
        out.push_str(&x.to_string());
    }
    out
}

impl fmt::Display for Unexpected {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Unexpected::Bool(b) => write!(f, "boolean `{}`", b),
            Unexpected::Unsigned(n) => write!(f, "integer `{}`", n),
            Unexpected::Signed(n) => write!(f, "integer `{}`", n),
            Unexpected::Float(v) => write!(f, "floating point `{}`", format_float(*v)),
            Unexpected::Str(s) => write!(f, "string {:?}", s),
            Unexpected::Unit => write!(f, "null"),
            Unexpected::Seq => write!(f, "sequence"),
            Unexpected::Map => write!(f, "map"),
        }
    }
}

pub fn invalid_type(unexp: &Unexpected, exp: &str) -> JsonError {
    JsonError::custom(format!("invalid type: {}, expected {}", unexp, exp))
}

pub fn invalid_value(unexp: &Unexpected, exp: &str) -> JsonError {
    JsonError::custom(format!("invalid value: {}, expected {}", unexp, exp))
}

pub fn invalid_length(len: usize, exp: &str) -> JsonError {
    JsonError::custom(format!("invalid length {}, expected {}", len, exp))
}

pub fn missing_field(name: &str) -> JsonError {
    JsonError::custom(format!("missing field `{}`", name))
}

pub fn duplicate_field(name: &str) -> JsonError {
    JsonError::custom(format!("duplicate field `{}`", name))
}

pub fn unknown_variant(variant: &str, expected: &[&str]) -> JsonError {
    if expected.is_empty() {
        return JsonError::custom(format!("unknown variant `{}`, there are no variants", variant));
    }
    let one_of = match expected.len() {
        1 => format!("`{}`", expected[0]),
        2 => format!("`{}` or `{}`", expected[0], expected[1]),
        _ => {
            let parts: Vec<String> = expected.iter().map(|n| format!("`{}`", n)).collect();
            format!("one of {}", parts.join(", "))
        }
    };
    JsonError::custom(format!("unknown variant `{}`, expected {}", variant, one_of))
}

enum Number {
    U64(u64),
    I64(i64),
    F64(f64),
}

impl Number {
    fn unexpected(&self) -> Unexpected {
        match self {
            Number::U64(n) => Unexpected::Unsigned(*n),
            Number::I64(n) => Unexpected::Signed(*n),
            Number::F64(f) => Unexpected::Float(*f),
        }
    }

    fn content(self) -> Content {
        match self {
            Number::U64(n) => Content::U64(n),
            Number::I64(n) => Content::I64(n),
            Number::F64(f) => Content::F64(f),
        }
    }
}

fn pow10_table() -> Vec<f64> {
    (0..309).map(|i| format!("1e{}", i).parse::<f64>().unwrap()).collect()
}

pub struct Parser<'a> {
    data: &'a [u8],
    idx: usize,
    line: usize,
    col: usize,
    ch: Option<u8>,
    pub remaining_depth: u8,
    pow10: Vec<f64>,
}

impl<'a> Parser<'a> {
    pub fn new(data: &'a [u8]) -> Parser<'a> {
        Parser { data, idx: 0, line: 1, col: 0, ch: None, remaining_depth: 128, pow10: pow10_table() }
    }

    fn pull(&mut self) -> Option<u8> {
        if self.idx < self.data.len() {
            let b = self.data[self.idx];
            self.idx += 1;
            if b == b'\n' {
                self.line += 1;
                self.col = 0;
            } else {
                self.col += 1;
            }
            Some(b)
        } else {
            None
        }
    }

    pub fn next(&mut self) -> Option<u8> {
        match self.ch.take() {
            Some(c) => Some(c),
            None => self.pull(),
        }
    }

    pub fn peek(&mut self) -> Option<u8> {
        match self.ch {
            Some(c) => Some(c),
            None => {
                let c = self.pull();
                self.ch = c;
                c
            }
        }
    }

    pub fn eat_char(&mut self) {
        self.ch = None;
    }

    fn peek_or_null(&mut self) -> u8 {
        self.peek().unwrap_or(0)
    }

    pub fn error(&self, code: Code) -> JsonError {
        JsonError { msg: code.message().to_string(), line: self.line, column: self.col }
    }

    pub fn fix_position(&self, err: JsonError) -> JsonError {
        if err.line == 0 {
            JsonError { msg: err.msg, line: self.line, column: self.col }
        } else {
            err
        }
    }

    pub fn parse_whitespace(&mut self) -> Option<u8> {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\n') | Some(b'\t') | Some(b'\r') => self.eat_char(),
                other => return other,
            }
        }
    }

    pub fn end(&mut self) -> Result<(), JsonError> {
        match self.parse_whitespace() {
            Some(_) => Err(self.error(Code::TrailingCharacters)),
            None => Ok(()),
        }
    }

    pub fn enter(&mut self) -> Result<(), JsonError> {
        self.remaining_depth -= 1;
        if self.remaining_depth == 0 {
            return Err(self.error(Code::RecursionLimitExceeded));
        }
        Ok(())
    }

    pub fn leave(&mut self) {
        self.remaining_depth += 1;
    }

    pub fn end_seq(&mut self) -> Result<(), JsonError> {
        match self.parse_whitespace() {
            Some(b']') => {
                self.eat_char();
                Ok(())
            }
            Some(b',') => {
                self.eat_char();
                match self.parse_whitespace() {
                    Some(b']') => Err(self.error(Code::TrailingComma)),
                    _ => Err(self.error(Code::TrailingCharacters)),
                }
            }
            Some(_) => Err(self.error(Code::TrailingCharacters)),
            None => Err(self.error(Code::EofWhileParsingList)),
        }
    }

    pub fn end_map(&mut self) -> Result<(), JsonError> {
        match self.parse_whitespace() {
            Some(b'}') => {
                self.eat_char();
                Ok(())
            }
            Some(b',') => Err(self.error(Code::TrailingComma)),
            Some(_) => Err(self.error(Code::TrailingCharacters)),
            None => Err(self.error(Code::EofWhileParsingObject)),
        }
    }

    pub fn parse_ident(&mut self, ident: &[u8]) -> Result<(), JsonError> {
        for &expected in ident {
            match self.next() {
                None => return Err(self.error(Code::EofWhileParsingValue)),
                Some(c) => {
                    if c != expected {
                        return Err(self.error(Code::ExpectedSomeIdent));
                    }
                }
            }
        }
        Ok(())
    }

    fn next_or_eof(&mut self) -> Result<u8, JsonError> {
        match self.next() {
            Some(b) => Ok(b),
            None => Err(self.error(Code::EofWhileParsingString)),
        }
    }

    fn peek_or_eof(&mut self) -> Result<u8, JsonError> {
        match self.peek() {
            Some(b) => Ok(b),
            None => Err(self.error(Code::EofWhileParsingString)),
        }
    }

    fn decode_hex_escape(&mut self) -> Result<u16, JsonError> {
        let mut n: u16 = 0;
        let mut ok = true;
        for _ in 0..4 {
            let c = self.next_or_eof()?;
            let v = match c {
                b'0'..=b'9' => c - b'0',
                b'a'..=b'f' => c - b'a' + 10,
                b'A'..=b'F' => c - b'A' + 10,
                _ => {
                    ok = false;
                    0
                }
            };
            n = (n << 4) | v as u16;
        }
        if ok {
            Ok(n)
        } else {
            Err(self.error(Code::InvalidEscape))
        }
    }

    fn push_codepoint(n: u32, scratch: &mut Vec<u8>) {
        let c = char::from_u32(n).unwrap_or('\u{fffd}');
        let mut buf = [0u8; 4];
        scratch.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
    }

    fn parse_unicode_escape(&mut self, scratch: &mut Vec<u8>) -> Result<(), JsonError> {
        let n = self.decode_hex_escape()?;
        if (0xDC00..=0xDFFF).contains(&n) {
            return Err(self.error(Code::LoneLeadingSurrogateInHexEscape));
        }
        if !(0xD800..=0xDBFF).contains(&n) {
            Self::push_codepoint(n as u32, scratch);
            return Ok(());
        }
        let n1 = n;
        if self.peek_or_eof()? == b'\\' {
            self.eat_char();
        } else {
            self.eat_char();
            return Err(self.error(Code::UnexpectedEndOfHexEscape));
        }
        if self.peek_or_eof()? == b'u' {
            self.eat_char();
        } else {
            self.eat_char();
            return Err(self.error(Code::UnexpectedEndOfHexEscape));
        }
        let n2 = self.decode_hex_escape()?;
        if !(0xDC00..=0xDFFF).contains(&n2) {
            return Err(self.error(Code::LoneLeadingSurrogateInHexEscape));
        }
        let n = ((((n1 - 0xD800) as u32) << 10) | (n2 - 0xDC00) as u32) + 0x1_0000;
        Self::push_codepoint(n, scratch);
        Ok(())
    }

    fn parse_escape(&mut self, scratch: &mut Vec<u8>) -> Result<(), JsonError> {
        let ch = self.next_or_eof()?;
        match ch {
            b'"' => scratch.push(b'"'),
            b'\\' => scratch.push(b'\\'),
            b'/' => scratch.push(b'/'),
            b'b' => scratch.push(b'\x08'),
            b'f' => scratch.push(b'\x0c'),
            b'n' => scratch.push(b'\n'),
            b'r' => scratch.push(b'\r'),
            b't' => scratch.push(b'\t'),
            b'u' => return self.parse_unicode_escape(scratch),
            _ => return Err(self.error(Code::InvalidEscape)),
        }
        Ok(())
    }

    /// Parses a string; the opening quote must already be consumed.
    pub fn parse_str(&mut self) -> Result<String, JsonError> {
        let mut scratch = Vec::new();
        loop {
            let ch = self.next_or_eof()?;
            match ch {
                b'"' => {
                    return match String::from_utf8(scratch) {
                        Ok(s) => Ok(s),
                        Err(_) => Err(self.error(Code::InvalidUnicodeCodePoint)),
                    };
                }
                b'\\' => self.parse_escape(&mut scratch)?,
                c if c < 0x20 => {
                    return Err(self.error(Code::ControlCharacterWhileParsingString));
                }
                c => scratch.push(c),
            }
        }
    }

    pub fn parse_object_colon(&mut self) -> Result<(), JsonError> {
        match self.parse_whitespace() {
            Some(b':') => {
                self.eat_char();
                Ok(())
            }
            Some(_) => Err(self.error(Code::ExpectedColon)),
            None => Err(self.error(Code::EofWhileParsingObject)),
        }
    }

    // ------------------------------------------------------------ numbers

    fn parse_integer(&mut self, positive: bool) -> Result<Number, JsonError> {
        let next = match self.next() {
            Some(b) => b,
            None => return Err(self.error(Code::EofWhileParsingValue)),
        };
        match next {
            b'0' => match self.peek_or_null() {
                b'0'..=b'9' => Err(self.error(Code::InvalidNumber)),
                _ => self.parse_number(positive, 0),
            },
            c @ b'1'..=b'9' => {
                let mut significand = (c - b'0') as u64;
                loop {
                    match self.peek_or_null() {
                        c @ b'0'..=b'9' => {
                            let digit = (c - b'0') as u64;
                            if overflow_u64(significand, digit) {
                                return Ok(Number::F64(self.parse_long_integer(positive, significand)?));
                            }
                            self.eat_char();
                            significand = significand * 10 + digit;
                        }
                        _ => return self.parse_number(positive, significand),
                    }
                }
            }
            _ => Err(self.error(Code::InvalidNumber)),
        }
    }

    fn parse_number(&mut self, positive: bool, significand: u64) -> Result<Number, JsonError> {
        Ok(match self.peek_or_null() {
            b'.' => Number::F64(self.parse_decimal(positive, significand, 0)?),
            b'e' | b'E' => Number::F64(self.parse_exponent(positive, significand, 0)?),
            _ => {
                if positive {
                    Number::U64(significand)
                } else {
                    let neg = (significand as i64).wrapping_neg();
                    if neg >= 0 {
                        Number::F64(-(significand as f64))
                    } else {
                        Number::I64(neg)
                    }
                }
            }
        })
    }

    fn parse_decimal(&mut self, positive: bool, mut significand: u64, exponent_before: i32) -> Result<f64, JsonError> {
        self.eat_char();
        let mut exponent_after: i32 = 0;
        loop {
            let c = self.peek_or_null();
            if !c.is_ascii_digit() {
                break;
            }
            let digit = (c - b'0') as u64;
            if overflow_u64(significand, digit) {
                let exponent = exponent_before + exponent_after;
                return self.parse_decimal_overflow(positive, significand, exponent);
            }
            self.eat_char();
            significand = significand * 10 + digit;
            exponent_after -= 1;
        }
        if exponent_after == 0 {
            match self.peek() {
                Some(_) => return Err(self.error(Code::InvalidNumber)),
                None => return Err(self.error(Code::EofWhileParsingValue)),
            }
        }
        let exponent = exponent_before + exponent_after;
        match self.peek_or_null() {
            b'e' | b'E' => self.parse_exponent(positive, significand, exponent),
            _ => self.f64_from_parts(positive, significand, exponent),
        }
    }

    fn parse_exponent(&mut self, positive: bool, significand: u64, starting_exp: i32) -> Result<f64, JsonError> {
        self.eat_char();
        let positive_exp = match self.peek_or_null() {
            b'+' => {
                self.eat_char();
                true
            }
            b'-' => {
                self.eat_char();
                false
            }
            _ => true,
        };
        let next = match self.next() {
            Some(b) => b,
            None => return Err(self.error(Code::EofWhileParsingValue)),
        };
        let mut exp = match next {
            c @ b'0'..=b'9' => (c - b'0') as i32,
            _ => return Err(self.error(Code::InvalidNumber)),
        };
        loop {
            let c = self.peek_or_null();
            if !c.is_ascii_digit() {
                break;
            }
            self.eat_char();
            let digit = (c - b'0') as i32;
            if exp >= i32::MAX / 10 && (exp > i32::MAX / 10 || digit > i32::MAX % 10) {
                let zero_significand = significand == 0;
                return self.parse_exponent_overflow(positive, zero_significand, positive_exp);
            }
            exp = exp * 10 + digit;
        }
        let final_exp = if positive_exp { starting_exp.saturating_add(exp) } else { starting_exp.saturating_sub(exp) };
        self.f64_from_parts(positive, significand, final_exp)
    }

    fn parse_exponent_overflow(&mut self, positive: bool, zero_significand: bool, positive_exp: bool) -> Result<f64, JsonError> {
        if !zero_significand && positive_exp {
            return Err(self.error(Code::NumberOutOfRange));
        }
        while self.peek_or_null().is_ascii_digit() {
            self.eat_char();
        }
        Ok(if positive { 0.0 } else { -0.0 })
    }

    fn parse_long_integer(&mut self, positive: bool, significand: u64) -> Result<f64, JsonError> {
        let mut exponent: i32 = 0;
        loop {
            match self.peek_or_null() {
                b'0'..=b'9' => {
                    self.eat_char();
                    exponent += 1;
                }
                b'.' => return self.parse_decimal(positive, significand, exponent),
                b'e' | b'E' => return self.parse_exponent(positive, significand, exponent),
                _ => return self.f64_from_parts(positive, significand, exponent),
            }
        }
    }

    fn parse_decimal_overflow(&mut self, positive: bool, significand: u64, exponent: i32) -> Result<f64, JsonError> {
        while self.peek_or_null().is_ascii_digit() {
            self.eat_char();
        }
        match self.peek_or_null() {
            b'e' | b'E' => self.parse_exponent(positive, significand, exponent),
            _ => self.f64_from_parts(positive, significand, exponent),
        }
    }

    fn f64_from_parts(&mut self, positive: bool, significand: u64, mut exponent: i32) -> Result<f64, JsonError> {
        let mut f = significand as f64;
        loop {
            match self.pow10.get(exponent.wrapping_abs() as usize) {
                Some(&pow) => {
                    if exponent >= 0 {
                        f *= pow;
                        if f.is_infinite() {
                            return Err(self.error(Code::NumberOutOfRange));
                        }
                    } else {
                        f /= pow;
                    }
                    break;
                }
                None => {
                    if f == 0.0 {
                        break;
                    }
                    if exponent >= 0 {
                        return Err(self.error(Code::NumberOutOfRange));
                    }
                    f /= 1e308;
                    exponent += 308;
                }
            }
        }
        Ok(if positive { f } else { -f })
    }

    // ------------------------------------------------------------ values

    /// Parses any value into a `Content` (equivalent of deserialize_any with a
    /// buffering visitor).
    pub fn parse_value(&mut self) -> Result<Content, JsonError> {
        let peek = match self.parse_whitespace() {
            Some(b) => b,
            None => return Err(self.error(Code::EofWhileParsingValue)),
        };
        let value = match peek {
            b'n' => {
                self.eat_char();
                self.parse_ident(b"ull")?;
                Ok(Content::Unit)
            }
            b't' => {
                self.eat_char();
                self.parse_ident(b"rue")?;
                Ok(Content::Bool(true))
            }
            b'f' => {
                self.eat_char();
                self.parse_ident(b"alse")?;
                Ok(Content::Bool(false))
            }
            b'-' => {
                self.eat_char();
                Ok(self.parse_integer(false)?.content())
            }
            b'0'..=b'9' => Ok(self.parse_integer(true)?.content()),
            b'"' => {
                self.eat_char();
                Ok(Content::String(self.parse_str()?))
            }
            b'[' => {
                self.enter()?;
                self.eat_char();
                let ret = self.parse_seq_content();
                self.leave();
                match (ret, self.end_seq()) {
                    (Ok(v), Ok(())) => Ok(Content::Seq(v)),
                    (Err(e), _) | (_, Err(e)) => Err(e),
                }
            }
            b'{' => {
                self.enter()?;
                self.eat_char();
                let ret = self.parse_map_content();
                self.leave();
                match (ret, self.end_map()) {
                    (Ok(v), Ok(())) => Ok(Content::Map(v)),
                    (Err(e), _) | (_, Err(e)) => Err(e),
                }
            }
            _ => Err(self.error(Code::ExpectedSomeValue)),
        };
        value.map_err(|e| self.fix_position(e))
    }

    /// Returns true if another sequence element follows.
    pub fn has_next_element(&mut self, first: &mut bool) -> Result<bool, JsonError> {
        let peek = match self.parse_whitespace() {
            Some(b']') => return Ok(false),
            Some(b',') if !*first => {
                self.eat_char();
                self.parse_whitespace()
            }
            Some(b) => {
                if *first {
                    *first = false;
                    Some(b)
                } else {
                    return Err(self.error(Code::ExpectedListCommaOrEnd));
                }
            }
            None => return Err(self.error(Code::EofWhileParsingList)),
        };
        match peek {
            Some(b']') => Err(self.error(Code::TrailingComma)),
            Some(_) => Ok(true),
            None => Err(self.error(Code::EofWhileParsingValue)),
        }
    }

    /// Returns true if another key follows (the key's quote is peeked).
    pub fn has_next_key(&mut self, first: &mut bool) -> Result<bool, JsonError> {
        let peek = match self.parse_whitespace() {
            Some(b'}') => return Ok(false),
            Some(b',') if !*first => {
                self.eat_char();
                self.parse_whitespace()
            }
            Some(b) => {
                if *first {
                    *first = false;
                    Some(b)
                } else {
                    return Err(self.error(Code::ExpectedObjectCommaOrEnd));
                }
            }
            None => return Err(self.error(Code::EofWhileParsingObject)),
        };
        match peek {
            Some(b'"') => Ok(true),
            Some(b'}') => Err(self.error(Code::TrailingComma)),
            Some(_) => Err(self.error(Code::KeyMustBeAString)),
            None => Err(self.error(Code::EofWhileParsingValue)),
        }
    }

    pub fn parse_key(&mut self) -> Result<String, JsonError> {
        self.eat_char();
        self.parse_str()
    }

    pub fn parse_seq_content(&mut self) -> Result<Vec<Content>, JsonError> {
        let mut out = Vec::new();
        let mut first = true;
        while self.has_next_element(&mut first)? {
            out.push(self.parse_value()?);
        }
        Ok(out)
    }

    fn parse_map_content(&mut self) -> Result<Vec<(Content, Content)>, JsonError> {
        let mut out = Vec::new();
        let mut first = true;
        while self.has_next_key(&mut first)? {
            let k = self.parse_key()?;
            self.parse_object_colon()?;
            let v = self.parse_value()?;
            out.push((Content::String(k), v));
        }
        Ok(out)
    }

    /// Equivalent of `peek_invalid_type`: consumes a scalar and builds the
    /// "invalid type" error for it.
    pub fn peek_invalid_type(&mut self, exp: &str) -> JsonError {
        let err = match self.peek_or_null() {
            b'n' => {
                self.eat_char();
                if let Err(e) = self.parse_ident(b"ull") {
                    return e;
                }
                invalid_type(&Unexpected::Unit, exp)
            }
            b't' => {
                self.eat_char();
                if let Err(e) = self.parse_ident(b"rue") {
                    return e;
                }
                invalid_type(&Unexpected::Bool(true), exp)
            }
            b'f' => {
                self.eat_char();
                if let Err(e) = self.parse_ident(b"alse") {
                    return e;
                }
                invalid_type(&Unexpected::Bool(false), exp)
            }
            b'-' => {
                self.eat_char();
                match self.parse_integer(false) {
                    Ok(n) => invalid_type(&n.unexpected(), exp),
                    Err(e) => return e,
                }
            }
            b'0'..=b'9' => match self.parse_integer(true) {
                Ok(n) => invalid_type(&n.unexpected(), exp),
                Err(e) => return e,
            },
            b'"' => {
                self.eat_char();
                match self.parse_str() {
                    Ok(s) => invalid_type(&Unexpected::Str(s), exp),
                    Err(e) => return e,
                }
            }
            b'[' => invalid_type(&Unexpected::Seq, exp),
            b'{' => invalid_type(&Unexpected::Map, exp),
            _ => self.error(Code::ExpectedSomeValue),
        };
        self.fix_position(err)
    }

    /// Scalar handling shared by visitors that only accept sequences or maps
    /// (deserialize_any with a visitor rejecting scalars).
    pub fn scalar_invalid(&mut self, peek: u8, exp: &str) -> Result<(), JsonError> {
        match peek {
            b'n' => {
                self.eat_char();
                self.parse_ident(b"ull")?;
                Err(invalid_type(&Unexpected::Unit, exp))
            }
            b't' => {
                self.eat_char();
                self.parse_ident(b"rue")?;
                Err(invalid_type(&Unexpected::Bool(true), exp))
            }
            b'f' => {
                self.eat_char();
                self.parse_ident(b"alse")?;
                Err(invalid_type(&Unexpected::Bool(false), exp))
            }
            b'-' => {
                self.eat_char();
                let n = self.parse_integer(false)?;
                Err(invalid_type(&n.unexpected(), exp))
            }
            b'0'..=b'9' => {
                let n = self.parse_integer(true)?;
                Err(invalid_type(&n.unexpected(), exp))
            }
            b'"' => {
                self.eat_char();
                let s = self.parse_str()?;
                Err(invalid_type(&Unexpected::Str(s), exp))
            }
            _ => Err(self.error(Code::ExpectedSomeValue)),
        }
    }
}

fn overflow_u64(a: u64, b: u64) -> bool {
    let c = u64::MAX;
    a >= c / 10 && (a > c / 10 || b > c % 10)
}
