//! Contract ABI model and its JSON deserialization.

use crate::json::{
    duplicate_field, invalid_length, invalid_type, invalid_value, missing_field, unknown_variant,
    Content, JsonError, Parser, Unexpected,
};
use crate::keccak::keccak256;
use crate::paramtype::{self, write_type, ParamType, ReadError};
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct Param {
    pub name: String,
    pub kind: ParamType,
}

#[derive(Debug, Clone)]
pub struct EventParam {
    pub name: String,
    pub kind: ParamType,
    pub indexed: bool,
}

#[derive(Debug, Clone)]
pub struct Function {
    pub name: String,
    pub inputs: Vec<Param>,
    pub outputs: Vec<Param>,
}

#[derive(Debug, Clone)]
pub struct Event {
    pub name: String,
    pub inputs: Vec<EventParam>,
    pub anonymous: bool,
}

#[derive(Debug, Default)]
pub struct Contract {
    pub functions: BTreeMap<String, Vec<Function>>,
    pub events: BTreeMap<String, Vec<Event>>,
}

fn join_types<'a, I: Iterator<Item = &'a ParamType>>(it: I) -> String {
    it.map(write_type).collect::<Vec<_>>().join(",")
}

impl Function {
    pub fn signature(&self) -> String {
        let inputs = join_types(self.inputs.iter().map(|p| &p.kind));
        let outputs = join_types(self.outputs.iter().map(|p| &p.kind));
        if outputs.is_empty() {
            format!("{}({})", self.name, inputs)
        } else {
            format!("{}({}):({})", self.name, inputs, outputs)
        }
    }

    pub fn short_signature(&self) -> [u8; 4] {
        let s = format!("{}({})", self.name, join_types(self.inputs.iter().map(|p| &p.kind)));
        let h = keccak256(s.as_bytes());
        [h[0], h[1], h[2], h[3]]
    }
}

impl Event {
    pub fn signature(&self) -> [u8; 32] {
        let s = format!("{}({})", self.name, join_types(self.inputs.iter().map(|p| &p.kind)));
        keccak256(s.as_bytes())
    }
}

pub fn hash_signature(sig: &str) -> [u8; 32] {
    keccak256(sig.as_bytes())
}

// ------------------------------------------------------------------ loading

const OPERATION_VARIANTS: &[&str] = &["constructor", "function", "event", "error", "fallback", "receive"];
const STATE_MUTABILITY_VARIANTS: &[&str] = &["pure", "view", "nonpayable", "payable"];

#[derive(Debug, Clone, Copy, PartialEq)]
enum OpTag {
    Constructor,
    Function,
    Event,
    Error,
    Fallback,
    Receive,
}

fn op_tag_from_str(s: &str) -> Result<OpTag, JsonError> {
    match s {
        "constructor" => Ok(OpTag::Constructor),
        "function" => Ok(OpTag::Function),
        "event" => Ok(OpTag::Event),
        "error" => Ok(OpTag::Error),
        "fallback" => Ok(OpTag::Fallback),
        "receive" => Ok(OpTag::Receive),
        _ => Err(unknown_variant(s, OPERATION_VARIANTS)),
    }
}

pub fn load(data: &[u8]) -> Result<Contract, JsonError> {
    let mut p = Parser::new(data);
    let c = deserialize_contract(&mut p)?;
    p.end()?;
    Ok(c)
}

const CONTRACT_EXP: &str = "valid abi spec file";
const OPERATION_EXP: &str = "internally tagged enum Operation";

fn deserialize_contract(p: &mut Parser) -> Result<Contract, JsonError> {
    let peek = match p.parse_whitespace() {
        Some(b) => b,
        None => return Err(p.error(crate::json::Code::EofWhileParsingValue)),
    };
    let value = match peek {
        b'[' => {
            p.enter()?;
            p.eat_char();
            let ret = visit_contract_seq(p);
            p.leave();
            match (ret, p.end_seq()) {
                (Ok(v), Ok(())) => Ok(v),
                (Err(e), _) | (_, Err(e)) => Err(e),
            }
        }
        b'{' => {
            p.enter()?;
            p.eat_char();
            let ret: Result<Contract, JsonError> = Err(invalid_type(&Unexpected::Map, CONTRACT_EXP));
            p.leave();
            match (ret, p.end_map()) {
                (Ok(v), Ok(())) => Ok(v),
                (Err(e), _) | (_, Err(e)) => Err(e),
            }
        }
        _ => p.scalar_invalid(peek, CONTRACT_EXP).map(|_| Contract::default()),
    };
    value.map_err(|e| p.fix_position(e))
}

fn visit_contract_seq(p: &mut Parser) -> Result<Contract, JsonError> {
    let mut result = Contract::default();
    let mut first = true;
    while p.has_next_element(&mut first)? {
        let (tag, content) = deserialize_operation(p)?;
        match tag {
            OpTag::Constructor => {
                struct_fields(content, "Constructor", &["inputs"], |f| {
                    let mut inputs: Option<Vec<Param>> = None;
                    f.each(|key, v| match key {
                        "inputs" => {
                            if inputs.is_some() {
                                return Err(duplicate_field("inputs"));
                            }
                            inputs = Some(seq_of(v, param_from_content)?);
                            Ok(())
                        }
                        _ => Ok(()),
                    }, |idx, v| {
                        if idx == 0 {
                            inputs = Some(seq_of(v, param_from_content)?);
                        }
                        Ok(())
                    })?;
                    inputs.ok_or_else(|| f.missing(0, "inputs"))?;
                    Ok(())
                })?;
            }
            OpTag::Function => {
                let func = function_from_content(content)?;
                result.functions.entry(func.name.clone()).or_default().push(func);
            }
            OpTag::Event => {
                let ev = event_from_content(content)?;
                result.events.entry(ev.name.clone()).or_default().push(ev);
            }
            OpTag::Error => {
                error_from_content(content)?;
            }
            OpTag::Fallback | OpTag::Receive => {}
        }
    }
    Ok(result)
}

/// deserialize_any with the internally-tagged-enum visitor.
fn deserialize_operation(p: &mut Parser) -> Result<(OpTag, Content), JsonError> {
    let peek = match p.parse_whitespace() {
        Some(b) => b,
        None => return Err(p.error(crate::json::Code::EofWhileParsingValue)),
    };
    let value = match peek {
        b'{' => {
            p.enter()?;
            p.eat_char();
            let ret = tagged_visit_map(p);
            p.leave();
            match (ret, p.end_map()) {
                (Ok(v), Ok(())) => Ok(v),
                (Err(e), _) | (_, Err(e)) => Err(e),
            }
        }
        b'[' => {
            p.enter()?;
            p.eat_char();
            let ret = tagged_visit_seq(p);
            p.leave();
            match (ret, p.end_seq()) {
                (Ok(v), Ok(())) => Ok(v),
                (Err(e), _) | (_, Err(e)) => Err(e),
            }
        }
        _ => p.scalar_invalid(peek, OPERATION_EXP).map(|_| (OpTag::Fallback, Content::Unit)),
    };
    value.map_err(|e| p.fix_position(e))
}

fn deserialize_variant_identifier(p: &mut Parser) -> Result<OpTag, JsonError> {
    let peek = match p.parse_whitespace() {
        Some(b) => b,
        None => return Err(p.error(crate::json::Code::EofWhileParsingValue)),
    };
    let value = match peek {
        b'"' => {
            p.eat_char();
            let s = p.parse_str()?;
            op_tag_from_str(&s)
        }
        _ => Err(p.peek_invalid_type("variant identifier")),
    };
    value.map_err(|e| p.fix_position(e))
}

fn tagged_visit_map(p: &mut Parser) -> Result<(OpTag, Content), JsonError> {
    let mut tag: Option<OpTag> = None;
    let mut vec = Vec::new();
    let mut first = true;
    while p.has_next_key(&mut first)? {
        let key = p.parse_key()?;
        if key == "type" {
            if tag.is_some() {
                return Err(duplicate_field("type"));
            }
            p.parse_object_colon()?;
            tag = Some(deserialize_variant_identifier(p)?);
        } else {
            p.parse_object_colon()?;
            let v = p.parse_value()?;
            vec.push((Content::String(key), v));
        }
    }
    match tag {
        None => Err(missing_field("type")),
        Some(t) => Ok((t, Content::Map(vec))),
    }
}

fn tagged_visit_seq(p: &mut Parser) -> Result<(OpTag, Content), JsonError> {
    let mut first = true;
    if !p.has_next_element(&mut first)? {
        return Err(missing_field("type"));
    }
    let tag = deserialize_variant_identifier(p)?;
    let mut rest = Vec::new();
    while p.has_next_element(&mut first)? {
        rest.push(p.parse_value()?);
    }
    Ok((tag, Content::Seq(rest)))
}

// ------------------------------------------------------- content helpers

/// Helper for derived struct deserialization from buffered content.
struct Fields {
    is_seq: bool,
    struct_desc: String,
    entries: Option<Vec<(Content, Content)>>,
    items: Option<Vec<Content>>,
}

impl Fields {
    fn each<F, G>(&mut self, mut on_key: F, mut on_index: G) -> Result<(), JsonError>
    where
        F: FnMut(&str, Content) -> Result<(), JsonError>,
        G: FnMut(usize, Content) -> Result<(), JsonError>,
    {
        if let Some(entries) = self.entries.take() {
            for (k, v) in entries {
                let key = match k {
                    Content::String(s) => s,
                    other => return Err(invalid_type(&other.unexpected(), "field identifier")),
                };
                on_key(&key, v)?;
            }
        }
        if let Some(items) = self.items.take() {
            for (i, v) in items.into_iter().enumerate() {
                on_index(i, v)?;
            }
        }
        Ok(())
    }

    fn missing(&self, idx: usize, name: &str) -> JsonError {
        if self.is_seq {
            invalid_length(idx, &self.struct_desc)
        } else {
            missing_field(name)
        }
    }
}

fn struct_fields<T, F>(content: Content, name: &str, fields: &[&str], f: F) -> Result<T, JsonError>
where
    F: FnOnce(&mut Fields) -> Result<T, JsonError>,
{
    let n = fields.len();
    let desc = format!("struct {} with {} element{}", name, n, if n == 1 { "" } else { "s" });
    match content {
        Content::Map(entries) => {
            let mut fl = Fields { is_seq: false, struct_desc: desc, entries: Some(entries), items: None };
            f(&mut fl)
        }
        Content::Seq(items) => {
            let total = items.len();
            let mut fl = Fields { is_seq: true, struct_desc: desc, entries: None, items: Some(items) };
            // Elements beyond the struct's fields are reported after the visit.
            let r = f(&mut fl)?;
            if total > n {
                return Err(invalid_length(
                    total,
                    &if n == 1 { "1 element in sequence".to_string() } else { format!("{} elements in sequence", n) },
                ));
            }
            Ok(r)
        }
        other => Err(invalid_type(&other.unexpected(), &format!("struct {}", name))),
    }
}

fn string_from(c: Content) -> Result<String, JsonError> {
    match c {
        Content::String(s) => Ok(s),
        other => Err(invalid_type(&other.unexpected(), "a string")),
    }
}

fn bool_from(c: Content) -> Result<bool, JsonError> {
    match c {
        Content::Bool(b) => Ok(b),
        other => Err(invalid_type(&other.unexpected(), "a boolean")),
    }
}

fn seq_of<T, F>(c: Content, mut f: F) -> Result<Vec<T>, JsonError>
where
    F: FnMut(Content) -> Result<T, JsonError>,
{
    match c {
        Content::Seq(items) => {
            let mut out = Vec::with_capacity(items.len());
            for it in items {
                out.push(f(it)?);
            }
            Ok(out)
        }
        other => Err(invalid_type(&other.unexpected(), "a sequence")),
    }
}

fn sanitize_name(mut name: String) -> String {
    if let Some(i) = name.find('(') {
        name.truncate(i);
    }
    name
}

fn param_type_from(c: Content) -> Result<ParamType, JsonError> {
    const EXP: &str = "a correct name of abi-encodable parameter type";
    match c {
        Content::String(s) => paramtype::read(&s).map_err(|e| {
            JsonError::custom(match e {
                ReadError::InvalidName(n) => format!("InvalidName({:?})", n),
                ReadError::ParseInt(p) => format!("ParseInt({:?})", p),
            })
        }),
        other => Err(invalid_type(&other.unexpected(), EXP)),
    }
}

fn inner_tuple_mut(mut param: &mut ParamType) -> Option<&mut Vec<ParamType>> {
    loop {
        match param {
            ParamType::Array(inner) => param = inner.as_mut(),
            ParamType::FixedArray(inner, _) => param = inner.as_mut(),
            ParamType::Tuple(inner) => return Some(inner),
            _ => return None,
        }
    }
}

fn set_tuple_components(kind: &mut ParamType, components: Option<Vec<ParamType>>) -> Result<(), JsonError> {
    if let Some(inner) = inner_tuple_mut(kind) {
        let comps = components.ok_or_else(|| missing_field("components"))?;
        inner.extend(comps);
    }
    Ok(())
}

fn map_entries(c: Content, exp: &str) -> Result<Vec<(String, Content)>, JsonError> {
    match c {
        Content::Map(entries) => {
            let mut out = Vec::with_capacity(entries.len());
            for (k, v) in entries {
                let key = match k {
                    Content::String(s) => s,
                    other => return Err(invalid_type(&other.unexpected(), "a string")),
                };
                out.push((key, v));
            }
            Ok(out)
        }
        other => Err(invalid_type(&other.unexpected(), exp)),
    }
}

fn param_from_content(c: Content) -> Result<Param, JsonError> {
    let entries = map_entries(c, "a valid event parameter spec")?;
    let mut name: Option<String> = None;
    let mut kind: Option<ParamType> = None;
    let mut internal_type: Option<String> = None;
    let mut components: Option<Vec<ParamType>> = None;
    for (key, v) in entries {
        match key.as_str() {
            "name" => {
                if name.is_some() {
                    return Err(duplicate_field("name"));
                }
                name = Some(string_from(v)?);
            }
            "type" => {
                if kind.is_some() {
                    return Err(duplicate_field("kind"));
                }
                kind = Some(param_type_from(v)?);
            }
            "internalType" => {
                if internal_type.is_some() {
                    return Err(duplicate_field("internalType"));
                }
                internal_type = Some(string_from(v)?);
            }
            "components" => {
                if components.is_some() {
                    return Err(duplicate_field("components"));
                }
                components = Some(seq_of(v, tuple_param_from_content)?);
            }
            _ => {}
        }
    }
    let name = name.ok_or_else(|| missing_field("name"))?;
    let mut kind = kind.ok_or_else(|| missing_field("kind"))?;
    set_tuple_components(&mut kind, components)?;
    Ok(Param { name, kind })
}

fn event_param_from_content(c: Content) -> Result<EventParam, JsonError> {
    let entries = map_entries(c, "a valid event parameter spec")?;
    let mut name: Option<String> = None;
    let mut kind: Option<ParamType> = None;
    let mut indexed: Option<bool> = None;
    let mut internal_type: Option<String> = None;
    let mut components: Option<Vec<ParamType>> = None;
    for (key, v) in entries {
        match key.as_str() {
            "name" => {
                if name.is_some() {
                    return Err(duplicate_field("name"));
                }
                name = Some(string_from(v)?);
            }
            "type" => {
                if kind.is_some() {
                    return Err(duplicate_field("kind"));
                }
                kind = Some(param_type_from(v)?);
            }
            "indexed" => {
                if indexed.is_some() {
                    return Err(duplicate_field("indexed"));
                }
                indexed = Some(bool_from(v)?);
            }
            "internalType" => {
                if internal_type.is_some() {
                    return Err(duplicate_field("internalType"));
                }
                internal_type = Some(string_from(v)?);
            }
            "components" => {
                if components.is_some() {
                    return Err(duplicate_field("components"));
                }
                components = Some(seq_of(v, tuple_param_from_content)?);
            }
            _ => {}
        }
    }
    let name = name.ok_or_else(|| missing_field("name"))?;
    let mut kind = kind.ok_or_else(|| missing_field("kind"))?;
    let indexed = indexed.unwrap_or(false);
    set_tuple_components(&mut kind, components)?;
    Ok(EventParam { name, kind, indexed })
}

fn tuple_param_from_content(c: Content) -> Result<ParamType, JsonError> {
    let entries = map_entries(c, "a valid tuple parameter spec")?;
    let mut name: Option<String> = None;
    let mut kind: Option<ParamType> = None;
    let mut internal_type: Option<String> = None;
    let mut components: Option<Vec<ParamType>> = None;
    for (key, v) in entries {
        match key.as_str() {
            "name" => {
                if name.is_some() {
                    return Err(duplicate_field("name"));
                }
                name = Some(string_from(v)?);
            }
            "type" => {
                if kind.is_some() {
                    return Err(duplicate_field("kind"));
                }
                kind = Some(param_type_from(v)?);
            }
            "internalType" => {
                if internal_type.is_some() {
                    return Err(duplicate_field("internalType"));
                }
                internal_type = Some(string_from(v)?);
            }
            "components" => {
                if components.is_some() {
                    return Err(duplicate_field("components"));
                }
                components = Some(seq_of(v, tuple_param_from_content)?);
            }
            _ => {}
        }
    }
    let _ = name;
    let mut kind = kind.ok_or_else(|| missing_field("kind"))?;
    set_tuple_components(&mut kind, components)?;
    Ok(kind)
}

fn state_mutability_from(c: Content) -> Result<(), JsonError> {
    let check = |s: &str| -> Result<(), JsonError> {
        if STATE_MUTABILITY_VARIANTS.contains(&s) {
            Ok(())
        } else {
