fn function_from_content(content: Content) -> Result<Function, JsonError> {
    const FIELDS: &[&str] = &["name", "inputs", "outputs", "constant", "stateMutability"];
    struct_fields(content, "Function", FIELDS, |f| {
        let mut name: Option<String> = None;
        let mut inputs: Option<Vec<Param>> = None;
        let mut outputs: Option<Vec<Param>> = None;
        let mut constant: Option<Option<bool>> = None;
        let mut state: Option<()> = None;
        {
            let mut on_field = |key: &str, v: Content| -> Result<(), JsonError> {
                match key {
                    "name" => {
                        if name.is_some() {
                            return Err(duplicate_field("name"));
                        }
                        name = Some(sanitize_name(string_from(v)?));
                    }
                    "inputs" => {
                        if inputs.is_some() {
                            return Err(duplicate_field("inputs"));
                        }
                        inputs = Some(seq_of(v, param_from_content)?);
                    }
                    "outputs" => {
                        if outputs.is_some() {
                            return Err(duplicate_field("outputs"));
                        }
                        outputs = Some(seq_of(v, param_from_content)?);
                    }
                    "constant" => {
                        if constant.is_some() {
                            return Err(duplicate_field("constant"));
                        }
                        constant = Some(match v {
                            Content::Unit => None,
                            other => Some(bool_from(other)?),
                        });
                    }
                    "stateMutability" => {
                        if state.is_some() {
                            return Err(duplicate_field("stateMutability"));
                        }
                        state_mutability_from(v)?;
                        state = Some(());
                    }
                    _ => {}
                }
                Ok(())
            };
            let mut keyed: Vec<(String, Content)> = Vec::new();
            let mut indexed: Vec<(usize, Content)> = Vec::new();
            f.each(
                |k, v| {
                    keyed.push((k.to_string(), v));
                    Ok(())
                },
                |i, v| {
                    indexed.push((i, v));
                    Ok(())
                },
            )?;
            for (k, v) in keyed {
                on_field(&k, v)?;
            }
            for (i, v) in indexed {
                if i < FIELDS.len() {
