/// Runs a derived-struct style visit over map or sequence content.  For
/// sequences the elements are mapped to the field names in order.
fn struct_fields<T, F>(content: Content, name: &str, fields: &[&str], f: F) -> Result<T, JsonError>
where
    F: FnOnce(&mut Fields) -> Result<T, JsonError>,
{
    let n = fields.len();
    let desc = format!("struct {} with {} element{}", name, n, if n == 1 { "" } else { "s" });
    match content {
        Content::Map(entries) => {
            let mut pairs = Vec::with_capacity(entries.len());
            for (k, v) in entries {
