            let mut fl = Fields { is_seq: false, struct_desc: desc, pairs };
            f(&mut fl)
        }
        Content::Seq(items) => {
            let total = items.len();
            let pairs: Vec<(String, Content)> =
                items.into_iter().take(n).enumerate().map(|(i, v)| (fields[i].to_string(), v)).collect();
            let mut fl = Fields { is_seq: true, struct_desc: desc, pairs };
            let r = f(&mut fl)?;
            if total > n {
                return Err(invalid_length(
                    total,
                    &if n == 1 { "1 element in sequence".to_string() } else { format!("{} elements in sequence", n) },
                ));
            }
            Ok(r)
        }
        other => Err(invalid_type(&other.unexpected(), &format!("struct {}", name))),
    }
}

