//! Command line parsing reproducing the behaviour of the reference argument
//! parser (usage strings, error messages, help output).

use std::io::IsTerminal;

pub const VERSION: &str = "18.0.0";

#[derive(Debug)]
pub enum Command {
    EncodeFunction { abi_path: String, name: String, params: Vec<String>, lenient: bool },
    EncodeParams { params: Vec<String>, lenient: bool },
    DecodeFunction { abi_path: String, name: String, data: String },
    DecodeParams { types: Vec<String>, data: String },
    DecodeLog { abi_path: String, name: String, topics: Vec<String>, data: String },
}

pub enum Outcome {
    Run(Command),
    /// Text to print (a newline is appended) and whether it goes to stdout
    /// (exit code 0) or stderr (exit code 1).
    Exit { text: String, stdout: bool },
}

struct Colors {
    on: bool,
}

impl Colors {
    fn error(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

/// Suggestions are always colored (independently of the terminal).
fn always_good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

// ------------------------------------------------------------ suggestions

fn jaro(a: &str, b: &str) -> f64 {
    if a == b {
        return 1.0;
    }
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let a_len = a_chars.len();
    let b_len = b_chars.len();
    if a_len == 0 || b_len == 0 || (a_len == 1 && b_len == 1) {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_char) in a_chars.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        for (j, b_char) in b_chars.iter().enumerate().take(max_bound + 1) {
            if min_bound <= j && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let d = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if d <= 1.0 {
        d
    } else {
        1.0
    }
}

fn did_you_mean<'a>(v: &str, possible: &[&'a str]) -> Option<&'a str> {
    let mut candidate: Option<(f64, &'a str)> = None;
    for pv in possible {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.unwrap().0 < confidence) {
            candidate = Some((confidence, pv));
        }
    }
    candidate.map(|c| c.1)
}

// ------------------------------------------------------------ definitions

#[derive(Clone, Copy, PartialEq)]
enum Leaf {
    EncodeFunction,
    EncodeParams,
    DecodeFunction,
    DecodeParams,
    DecodeLog,
}

#[derive(Clone, Copy, PartialEq)]
enum Parent {
    Top,
    Encode,
    Decode,
}

struct FlagDef {
    name: &'static str,
    short: char,
    long: &'static str,
}

struct OptDef {
    name: &'static str,
    short: char,
    num_vals: usize,
    allow_hyphen: bool,
    display: &'static str,
}

struct LeafDef {
    flags: Vec<FlagDef>,
    opts: Vec<OptDef>,
    positionals: Vec<&'static str>,
    help_usage_tail: &'static str,
    short_help_body: &'static str,
    long_help_body: Option<&'static str>,
    about: &'static str,
}

fn leaf_def(leaf: Leaf) -> LeafDef {
    let lenient = FlagDef { name: "lenient", short: 'l', long: "lenient" };
    let help = FlagDef { name: "help", short: 'h', long: "help" };
    let version = FlagDef { name: "version", short: 'V', long: "version" };
    match leaf {
        Leaf::EncodeFunction => LeafDef {
            flags: vec![lenient, help, version],
            opts: vec![OptDef { name: "params", short: 'p', num_vals: 1, allow_hyphen: false, display: "-p <params>..." }],
            positionals: vec!["abi-path", "function-name-or-signature"],
            help_usage_tail: " [FLAGS] [OPTIONS] <abi-path> <function-name-or-signature>",
            about: "Load function from JSON ABI file",
            short_help_body: "FLAGS:
    -h, --help       Prints help information
    -l, --lenient    Allow short representation of input params
    -V, --version    Prints version information

OPTIONS:
    -p <params>...        

ARGS:
    <abi-path>                      
    <function-name-or-signature>    ",
            long_help_body: None,
        },
        Leaf::EncodeParams => LeafDef {
            flags: vec![lenient, help, version],
            opts: vec![OptDef {
                name: "type-or-param",
                short: 'v',
                num_vals: 2,
                allow_hyphen: true,
                display: "-v <type-or-param> <type-or-param>",
            }],
            positionals: vec![],
            help_usage_tail: " [FLAGS] [OPTIONS]",
            about: "Specify types of input params inline",
            short_help_body: "FLAGS:
    -h, --help       Prints help information
    -l, --lenient    Allow short representation of input params (numbers are in decimal form)
    -V, --version    Prints version information

OPTIONS:
    -v <type-or-param> <type-or-param>        Pairs of types directly followed by params in the form:",
            long_help_body: Some(
                "FLAGS:
    -h, --help       
            Prints help information

    -l, --lenient    
            Allow short representation of input params (numbers are in decimal form)

    -V, --version    
            Prints version information


OPTIONS:
    -v <type-or-param> <type-or-param>        
            Pairs of types directly followed by params in the form:

            -v <type1> <param1> -v <type2> <param2> ...",
            ),
        },
        Leaf::DecodeFunction => LeafDef {
            flags: vec![help, version],
            opts: vec![],
            positionals: vec!["abi-path", "function-name-or-signature", "data"],
            help_usage_tail: " <abi-path> <function-name-or-signature> <data>",
            about: "Load function from JSON ABI file",
            short_help_body: "FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

ARGS:
    <abi-path>                      
    <function-name-or-signature>    
    <data>                          ",
            long_help_body: None,
        },
        Leaf::DecodeParams => LeafDef {
            flags: vec![help, version],
            opts: vec![OptDef { name: "type", short: 't', num_vals: 1, allow_hyphen: false, display: "-t <type>..." }],
            positionals: vec!["data"],
            help_usage_tail: " [OPTIONS] <data>",
            about: "Specify types of input params inline",
            short_help_body: "FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

OPTIONS:
    -t <type>...        

ARGS:
    <data>    ",
            long_help_body: None,
        },
        Leaf::DecodeLog => LeafDef {
            flags: vec![help, version],
            opts: vec![OptDef { name: "topic", short: 'l', num_vals: 1, allow_hyphen: false, display: "-l <topic>..." }],
            positionals: vec!["abi-path", "event-name-or-signature", "data"],
            help_usage_tail: " [OPTIONS] <abi-path> <event-name-or-signature> <data>",
            about: "Decode event log",
            short_help_body: "FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

OPTIONS:
    -l <topic>...        

ARGS:
    <abi-path>                   
    <event-name-or-signature>    
    <data>                       ",
            long_help_body: None,
        },
    }
}

fn parent_subcommands(p: Parent) -> &'static [&'static str] {
    match p {
        Parent::Top => &["encode", "decode", "help"],
        Parent::Encode => &["function", "params", "help"],
        Parent::Decode => &["function", "params", "log", "help"],
    }
}

/// Long flags of the (not yet parsed) subcommands of a parent, as seen when
/// computing "did you mean to put ... after the subcommand" suggestions.
fn parent_sub_longs(p: Parent, sub: &str) -> &'static [&'static str] {
    match (p, sub) {
        (Parent::Encode, "function") | (Parent::Encode, "params") => &["lenient"],
        _ => &[],
    }
}

fn header_name(bin_name: &str, meta_name: &str) -> String {
    if bin_name.contains(' ') {
        bin_name.replace(' ', "-")
    } else {
        meta_name.to_string()
    }
}

fn parent_meta_name(p: Parent) -> &'static str {
    match p {
        Parent::Top => "ethabi-cli",
        Parent::Encode => "encode",
        Parent::Decode => "decode",
    }
}

fn parent_help(p: Parent, bin_name: &str) -> String {
    let header = format!("{} {}", header_name(bin_name, parent_meta_name(p)), VERSION);
    let (about, subs) = match p {
        Parent::Top => (
            "Ethereum ABI coder",
            "    decode    Decode ABI call result
    encode    Encode ABI call
    help      Prints this message or the help of the given subcommand(s)",
        ),
        Parent::Encode => (
            "Encode ABI call",
            "    function    Load function from JSON ABI file
    help        Prints this message or the help of the given subcommand(s)
    params      Specify types of input params inline",
        ),
        Parent::Decode => (
            "Decode ABI call result",
            "    function    Load function from JSON ABI file
    help        Prints this message or the help of the given subcommand(s)
    log         Decode event log
    params      Specify types of input params inline",
        ),
    };
    format!(
        "{}\n{}\n\nUSAGE:\n    {} <SUBCOMMAND>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nSUBCOMMANDS:\n{}",
        header, about, bin_name, subs
    )
}

fn help_help_text(bin_name: &str) -> String {
    format!(
        "{} \nPrints this message or the help of the given subcommand(s)\n\nUSAGE:\n    {} [subcommand]...\n\nARGS:\n    <subcommand>...    The subcommand whose help message to display",
        header_name(bin_name, "help"),
        bin_name
    )
}

fn leaf_meta_name(leaf: Leaf) -> &'static str {
    match leaf {
        Leaf::EncodeFunction | Leaf::DecodeFunction => "function",
        Leaf::EncodeParams | Leaf::DecodeParams => "params",
        Leaf::DecodeLog => "log",
    }
}

fn leaf_help(leaf: Leaf, bin_name: &str, long: bool) -> String {
    let def = leaf_def(leaf);
    let header = format!("{} {}", header_name(bin_name, leaf_meta_name(leaf)), VERSION);
    let body = if long { def.long_help_body.unwrap_or(def.short_help_body) } else { def.short_help_body };
    format!("{}\n{}\n\nUSAGE:\n    {}{}\n\n{}", header, def.about, bin_name, def.help_usage_tail, body)
}

fn version_text(bin_name: &str, meta_name: &str) -> String {
    format!("{} {}", header_name(bin_name, meta_name), VERSION)
}

pub struct Cli {
    colors: Colors,
}

impl Cli {
    pub fn new() -> Cli {
        let tty = std::io::stderr().is_terminal();
        let dumb = std::env::var("TERM").map(|t| t == "dumb").unwrap_or(false);
        Cli { colors: Colors { on: tty && !dumb } }
    }

    fn err(&self, text: String) -> Outcome {
        Outcome::Exit { text, stdout: false }
    }

    fn unknown_argument(&self, arg: &str, suffix: &str, usage: &str) -> Outcome {
        let c = &self.colors;
        let sfx = if suffix.is_empty() { "\n".to_string() } else { format!("{}\n", suffix) };
        self.err(format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(arg),
            sfx,
            usage,
            c.good("--help")
        ))
    }

    fn invalid_subcommand(&self, sub: &str, dym: &str, name: &str, usage: &str) -> Outcome {
        let c = &self.colors;
        self.err(format!(
            "{} The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} {} {}'\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(sub),
            c.good(dym),
            name,
            c.good("--"),
            sub,
            usage,
            c.good("--help")
        ))
    }

    fn unrecognized_subcommand(&self, sub: &str, name: &str) -> Outcome {
        let c = &self.colors;
        self.err(format!(
            "{} The subcommand '{}' wasn't recognized\n\n{}\n\t{} help <subcommands>...\n\nFor more information try {}",
            c.error("error:"),
            c.warning(sub),
            c.warning("USAGE:"),
            name,
            c.good("--help")
        ))
    }

    fn empty_value(&self, arg: &str, usage: &str) -> Outcome {
        let c = &self.colors;
        self.err(format!(
            "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(arg),
            usage,
            c.good("--help")
        ))
    }

    fn wrong_number_of_values(&self, arg: &str, num: usize, curr: usize, suffix: &str, usage: &str) -> Outcome {
        let c = &self.colors;
        self.err(format!(
            "{} The argument '{}' requires {} values, but {} w{} provided\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(arg),
            c.warning(&num.to_string()),
            c.warning(&curr.to_string()),
            suffix,
            usage,
            c.good("--help")
        ))
    }

    fn unexpected_multiple_usage(&self, arg: &str, usage: &str) -> Outcome {
        let c = &self.colors;
        self.err(format!(
            "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(arg),
            usage,
            c.good("--help")
        ))
    }

    fn missing_required(&self, required: &[&str], usage: &str) -> Outcome {
        let c = &self.colors;
        let req: String = required.iter().map(|s| format!("\n    {}", c.error(s))).collect();
        self.err(format!(
            "{} The following required arguments were not provided:{}\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            req,
            usage,
            c.good("--help")
        ))
    }

    pub fn parse(&self, args: Vec<String>) -> Outcome {
        let mut it = args.into_iter();
        let bin = match it.next() {
            Some(a0) => std::path::Path::new(&a0)
                .file_name()
                .and_then(|f| f.to_str())
                .map(|s| s.to_string())
                .unwrap_or_else(|| "ethabi-cli".to_string()),
            None => "ethabi-cli".to_string(),
        };
        let rest: Vec<String> = it.collect();
        self.parse_parent(Parent::Top, bin, &rest)
    }

    fn parent_usage(&self, bin_name: &str, used: Option<&str>) -> String {
        match used {
            Some(u) => format!("USAGE:\n    {} {}", bin_name, u),
            None => format!("USAGE:\n    {} <SUBCOMMAND>", bin_name),
        }
    }

    fn parse_parent(&self, p: Parent, bin_name: String, args: &[String]) -> Outcome {
        let subs = parent_subcommands(p);
        let mut trailing = false;
        for (i, arg) in args.iter().enumerate() {
            if !trailing && arg == "--" {
                trailing = true;
                continue;
            }
            if !trailing {
                if subs.contains(&arg.as_str()) {
                    let rest = &args[i + 1..];
                    if arg == "help" {
                        return self.help_subcommand(p, &bin_name, rest);
                    }
                    let sub_bin = format!("{} {}", bin_name, arg);
                    return match (p, arg.as_str()) {
                        (Parent::Top, "encode") => self.parse_parent(Parent::Encode, sub_bin, rest),
                        (Parent::Top, "decode") => self.parse_parent(Parent::Decode, sub_bin, rest),
                        (Parent::Encode, "function") => self.parse_leaf(Leaf::EncodeFunction, sub_bin, rest),
                        (Parent::Encode, "params") => self.parse_leaf(Leaf::EncodeParams, sub_bin, rest),
                        (Parent::Decode, "function") => self.parse_leaf(Leaf::DecodeFunction, sub_bin, rest),
                        (Parent::Decode, "params") => self.parse_leaf(Leaf::DecodeParams, sub_bin, rest),
                        (Parent::Decode, "log") => self.parse_leaf(Leaf::DecodeLog, sub_bin, rest),
                        _ => unreachable!(),
                    };
                }
                if arg.starts_with("--") {
                    let trimmed = arg.trim_start_matches('-');
                    let name = match trimmed.find('=') {
                        Some(idx) if arg.contains('=') => &trimmed[..idx],
                        _ => trimmed,
                    };
                    match name {
                        "help" => return Outcome::Exit { text: parent_help(p, &bin_name), stdout: true },
                        "version" => {
                            return Outcome::Exit {
                                text: version_text(&bin_name, parent_meta_name(p)),
                                stdout: true,
                            }
                        }
                        _ => {}
                    }
                    // did you mean
                    let longs = ["help", "version"];
                    let rest: Vec<&str> = args[i + 1..].iter().map(|s| s.as_str()).collect();
                    let mut suffix = String::new();
                    let mut used: Option<&str> = None;
                    if let Some(cand) = did_you_mean(name, &longs) {
                        suffix = format!("\n\tDid you mean {}{}?", always_good("--"), always_good(cand));
                        used = Some(if cand == "help" { "--help" } else { "--version" });
                    } else {
                        let mut best: Option<(usize, &str, &str)> = None;
                        for sub in subs {
                            let sl = parent_sub_longs(p, sub);
                            if let Some(cand) = did_you_mean(name, sl) {
                                if let Some(pos) = rest.iter().position(|x| x == sub) {
                                    if best.map_or(true, |b| pos < b.0) {
                                        best = Some((pos, cand, sub));
                                    }
                                }
                            }
                        }
                        if let Some((_, cand, sub)) = best {
                            suffix = format!(
                                "\n\tDid you mean to put '{}{}' after the subcommand '{}'?",
                                always_good("--"),
                                always_good(cand),
                                always_good(sub)
                            );
                        }
                    }
                    let usage = self.parent_usage(&bin_name, used);
                    return self.unknown_argument(&format!("--{}", name), &suffix, &usage);
                } else if arg.starts_with('-') && arg.len() != 1 {
                    let trimmed = arg.trim_start_matches('-');
                    for c in trimmed.chars() {
                        match c {
                            'h' => return Outcome::Exit { text: parent_help(p, &bin_name), stdout: true },
                            'V' => {
                                return Outcome::Exit {
                                    text: version_text(&bin_name, parent_meta_name(p)),
                                    stdout: true,
                                }
                            }
                            _ => {
                                let usage = self.parent_usage(&bin_name, None);
                                return self.unknown_argument(&format!("-{}", c), "", &usage);
                            }
                        }
                    }
                }
            }
            if let Some(cand) = did_you_mean(arg, subs) {
                let usage = self.parent_usage(&bin_name, None);
                return self.invalid_subcommand(arg, cand, &bin_name, &usage);
            }
            let usage = self.parent_usage(&bin_name, None);
            return self.unknown_argument(arg, "", &usage);
        }
        Outcome::Exit { text: parent_help(p, &bin_name), stdout: false }
    }

    fn help_subcommand(&self, p: Parent, bin_name: &str, cmds: &[String]) -> Outcome {
        // State of the "current" app while walking the given names.
        #[derive(Clone, Copy)]
        enum Node {
            Parent(Parent, bool), // bool: whether the help subcommand is present
            Leaf(Leaf),
            Help,
        }
        let mut help_help = false;
        let mut cur_bin = bin_name.to_string();
        let mut node = Node::Parent(p, true);
        let n = cmds.len();
        for (i, cmd) in cmds.iter().enumerate() {
            if cmd == "help" {
                help_help = true;
            }
            let next = match node {
                Node::Parent(pp, has_help) => {
                    let subs = parent_subcommands(pp);
                    if subs.contains(&cmd.as_str()) && (cmd != "help" || has_help) {
                        Some(match (pp, cmd.as_str()) {
                            (_, "help") => Node::Help,
                            (Parent::Top, "encode") => Node::Parent(Parent::Encode, false),
                            (Parent::Top, "decode") => Node::Parent(Parent::Decode, false),
                            (Parent::Encode, "function") => Node::Leaf(Leaf::EncodeFunction),
                            (Parent::Encode, "params") => Node::Leaf(Leaf::EncodeParams),
                            (Parent::Decode, "function") => Node::Leaf(Leaf::DecodeFunction),
                            (Parent::Decode, "params") => Node::Leaf(Leaf::DecodeParams),
                            (Parent::Decode, "log") => Node::Leaf(Leaf::DecodeLog),
                            _ => unreachable!(),
                        })
                    } else {
                        None
                    }
                }
                _ => None,
            };
            match next {
                Some(nn) => {
                    node = nn;
                    if i == n - 1 {
                        break;
                    }
                }
                None => return self.unrecognized_subcommand(cmd, bin_name),
            }
            let name = match node {
                Node::Parent(pp, _) => parent_meta_name(pp),
                Node::Leaf(l) => leaf_meta_name(l),
                Node::Help => "help",
            };
            cur_bin = format!("{} {}", cur_bin, name);
        }
        let sc_bin = if n == 0 {
            bin_name.to_string()
        } else {
            let name = match node {
                Node::Parent(pp, _) => parent_meta_name(pp),
                Node::Leaf(l) => leaf_meta_name(l),
                Node::Help => "help",
            };
            format!("{} {}", cur_bin, name)
        };
        let text = match node {
            Node::Help => {
                if help_help {
                    help_help_text(&sc_bin)
                } else {
                    help_help_text(&sc_bin)
                }
            }
            Node::Parent(pp, _) => parent_help(pp, &sc_bin),
            Node::Leaf(l) => leaf_help(l, &sc_bin, false),
        };
        Outcome::Exit { text, stdout: true }
    }

    fn parse_leaf(&self, leaf: Leaf, bin_name: String, args: &[String]) -> Outcome {
        let def = leaf_def(leaf);
        LeafParser::new(self, leaf, def, bin_name).run(args)
    }
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum PR {
    NotFound,
    Flag,
    Opt(usize),
    ValuesDone,
}

struct Matched {
    name: &'static str,
    occurs: usize,
    vals: Vec<String>,
}

struct LeafParser<'c> {
    cli: &'c Cli,
    leaf: Leaf,
    def: LeafDef,
    bin: String,
    matched: Vec<Matched>,
    pos_vals: Vec<String>,
}

impl<'c> LeafParser<'c> {
    fn new(cli: &'c Cli, leaf: Leaf, def: LeafDef, bin: String) -> LeafParser<'c> {
        LeafParser { cli, leaf, def, bin, matched: vec![], pos_vals: vec![] }
    }

    fn entry(&mut self, name: &'static str) -> &mut Matched {
        if let Some(i) = self.matched.iter().position(|m| m.name == name) {
            &mut self.matched[i]
        } else {
            self.matched.push(Matched { name, occurs: 0, vals: vec![] });
            self.matched.last_mut().unwrap()
        }
    }

    fn inc_occurrence(&mut self, name: &'static str) {
        self.entry(name).occurs += 1;
    }

    fn get(&self, name: &str) -> Option<&Matched> {
        self.matched.iter().find(|m| m.name == name)
    }

    fn display_of(&self, name: &str) -> String {
        if let Some(f) = self.def.flags.iter().find(|f| f.name == name) {
            return format!("--{}", f.long);
        }
        if let Some(o) = self.def.opts.iter().find(|o| o.name == name) {
            return o.display.to_string();
        }
        format!("<{}>", name)
    }

    /// Usage line used in error messages.
    fn error_usage(&self) -> String {
        let mut used: Vec<&str> = self.matched.iter().map(|m| m.name).collect();
        if used.is_empty() {
            return format!("USAGE:\n    {}{}", self.bin, self.def.help_usage_tail);
        }
        used.sort();
        used.dedup();
        let mut s = format!("USAGE:\n    {}", self.bin);
        for p in &self.def.positionals {
            s.push_str(&format!(" <{}>", p));
        }
        for u in used {
            s.push(' ');
            s.push_str(&self.display_of(u));
        }
        s
    }

    fn help(&self, long: bool) -> Outcome {
        Outcome::Exit { text: leaf_help(self.leaf, &self.bin, long), stdout: true }
    }

    fn version(&self) -> Outcome {
        Outcome::Exit { text: version_text(&self.bin, leaf_meta_name(self.leaf)), stdout: true }
    }

    fn needs_more_vals(&self, opt_idx: usize) -> bool {
        let o = &self.def.opts[opt_idx];
        match self.get(o.name) {
            Some(m) => m.vals.len() % o.num_vals != 0,
            None => true,
        }
    }

    fn add_val(&mut self, opt_idx: usize, v: &str) -> PR {
        let name = self.def.opts[opt_idx].name;
        self.entry(name).vals.push(v.to_string());
        if self.needs_more_vals(opt_idx) {
            PR::Opt(opt_idx)
        } else {
            PR::ValuesDone
        }
    }

    fn parse_opt(&mut self, val: Option<&str>, opt_idx: usize, had_eq: bool) -> PR {
        let no_val = val.is_none();
        let mut has_eq = false;
        if let Some(fv) = val {
            has_eq = fv.starts_with('=') || had_eq;
            let v = fv.trim_start_matches('=');
            self.add_val(opt_idx, v);
        }
        let name = self.def.opts[opt_idx].name;
        self.inc_occurrence(name);
        if no_val || (!has_eq && self.needs_more_vals(opt_idx)) {
            return PR::Opt(opt_idx);
        }
        PR::ValuesDone
    }

    fn is_new_arg(&self, arg: &str, needs: PR) -> bool {
        let allows_tac = match needs {
            PR::Opt(i) => self.def.opts[i].allow_hyphen,
            PR::ValuesDone => return true,
            _ => false,
        };
        let ret = if arg.starts_with("--") {
            if arg.len() == 2 && !allows_tac {
                return true;
            } else if allows_tac {
                return false;
            }
            true
        } else if arg.starts_with('-') {
            arg.len() != 1
        } else {
            false
        };
        ret && !allows_tac
    }

    fn run(mut self, args: &[String]) -> Outcome {
        let mut needs = PR::NotFound;
        let mut trailing = false;
        for (i, arg) in args.iter().enumerate() {
            let starts_new_arg = self.is_new_arg(arg, needs);
            if !trailing && arg == "--" && starts_new_arg {
                trailing = true;
                continue;
            }
            if !trailing {
                if starts_new_arg {
                    if arg.starts_with("--") {
                        match self.parse_long(arg, &args[i + 1..]) {
                            Ok(r) => {
                                needs = r;
                                match r {
                                    PR::Flag | PR::Opt(_) | PR::ValuesDone => continue,
                                    _ => {}
                                }
                            }
                            Err(o) => return o,
                        }
                    } else if arg.starts_with('-') && arg.len() != 1 {
                        match self.parse_short(arg) {
                            Ok(r) => {
                                needs = r;
                                match r {
                                    PR::Flag | PR::Opt(_) | PR::ValuesDone => continue,
                                    _ => {}
                                }
                            }
                            Err(o) => return o,
                        }
                    }
                } else if let PR::Opt(idx) = needs {
                    needs = self.add_val(idx, arg);
                    continue;
                }
            }
            // positional
            if self.pos_vals.len() < self.def.positionals.len() {
                self.pos_vals.push(arg.clone());
            } else {
                let usage = self.error_usage();
                return self.cli.unknown_argument(arg, "", &usage);
            }
        }
        // validation
        let mut reqs_validated = false;
        if let PR::Opt(idx) = needs {
            if let Some(o) = self.validate_required() {
                return o;
            }
            reqs_validated = true;
            let name = self.def.opts[idx].name;
            let empty = self.get(name).map_or(true, |m| m.vals.is_empty());
            if empty {
                let usage = self.error_usage();
                return self.cli.empty_value(self.def.opts[idx].display, &usage);
            }
        }
        if !reqs_validated {
            if let Some(o) = self.validate_required() {
                return o;
            }
        }
        for m in &self.matched {
            if let Some(o) = self.def.opts.iter().find(|o| o.name == m.name) {
                let n = m.vals.len();
                if n % o.num_vals != 0 {
                    let curr = n % o.num_vals;
                    let suffix = if n == 1 || curr == 1 { "as" } else { "ere" };
                    let usage = self.error_usage();
                    return self.cli.wrong_number_of_values(o.display, o.num_vals, curr, suffix, &usage);
                }
                if n == 0 {
                    let usage = self.error_usage();
                    return self.cli.empty_value(o.display, &usage);
                }
            } else if let Some(f) = self.def.flags.iter().find(|f| f.name == m.name) {
                if m.occurs > 1 {
                    let usage = self.error_usage();
                    return self.cli.unexpected_multiple_usage(&format!("--{}", f.long), &usage);
                }
            }
        }
        Outcome::Run(self.build())
    }

    fn validate_required(&self) -> Option<Outcome> {
        let have = self.pos_vals.len();
        if have < self.def.positionals.len() {
            let missing: Vec<String> = self.def.positionals[have..].iter().map(|p| format!("<{}>", p)).collect();
            let missing_refs: Vec<&str> = missing.iter().map(|s| s.as_str()).collect();
            let usage = self.error_usage();
            return Some(self.cli.missing_required(&missing_refs, &usage));
        }
        None
    }

    fn parse_long(&mut self, arg: &str, rest: &[String]) -> Result<PR, Outcome> {
        let trimmed = arg.trim_start_matches('-');
        let name = if arg.contains('=') {
            match trimmed.find('=') {
                Some(idx) => &trimmed[..idx],
                None => trimmed,
            }
        } else {
            trimmed
        };
        if let Some(fi) = self.def.flags.iter().position(|f| f.long == name) {
            let fname = self.def.flags[fi].name;
            match fname {
                "help" => return Err(self.help(true)),
                "version" => return Err(self.version()),
                _ => {}
            }
            self.inc_occurrence(fname);
            return Ok(PR::Flag);
        }
        // did you mean
        let _ = rest;
        let longs: Vec<&'static str> = self.def.flags.iter().map(|f| f.long).collect();
        let mut suffix = String::new();
        if let Some(cand) = did_you_mean(name, &longs) {
            suffix = format!("\n\tDid you mean {}{}?", always_good("--"), always_good(cand));
            let fname = self.def.flags.iter().find(|f| f.long == cand).unwrap().name;
            // inserting into the matches (resets occurrences)
            if let Some(i) = self.matched.iter().position(|m| m.name == fname) {
                self.matched[i].occurs = 1;
            } else {
                self.matched.push(Matched { name: fname, occurs: 1, vals: vec![] });
            }
        }
        let usage = self.error_usage();
        Err(self.cli.unknown_argument(&format!("--{}", name), &suffix, &usage))
    }

    fn parse_short(&mut self, arg: &str) -> Result<PR, Outcome> {
        let trimmed = arg.trim_start_matches('-');
        let mut ret = PR::NotFound;
        for (bi, c) in trimmed.char_indices() {
            if let Some(oi) = self.def.opts.iter().position(|o| o.short == c) {
                let after = bi + c.len_utf8();
                let val = if after < trimmed.len() { Some(&trimmed[after..]) } else { None };
                return Ok(self.parse_opt(val, oi, false));
            } else if let Some(fi) = self.def.flags.iter().position(|f| f.short == c) {
                let fname = self.def.flags[fi].name;
                match fname {
                    "help" => return Err(self.help(false)),
                    "version" => return Err(self.version()),
                    _ => {}
                }
                self.inc_occurrence(fname);
                ret = PR::Flag;
            } else {
                let usage = self.error_usage();
                return Err(self.cli.unknown_argument(&format!("-{}", c), "", &usage));
            }
        }
        Ok(ret)
    }

    fn vals(&self, name: &str) -> Vec<String> {
        self.get(name).map(|m| m.vals.clone()).unwrap_or_default()
    }

    fn flag(&self, name: &str) -> bool {
        self.get(name).map_or(false, |m| m.occurs > 0)
    }

    fn build(&self) -> Command {
        let p = |i: usize| self.pos_vals.get(i).cloned().unwrap_or_default();
        match self.leaf {
            Leaf::EncodeFunction => Command::EncodeFunction {
                abi_path: p(0),
                name: p(1),
                params: self.vals("params"),
                lenient: self.flag("lenient"),
            },
            Leaf::EncodeParams => Command::EncodeParams { params: self.vals("type-or-param"), lenient: self.flag("lenient") },
            Leaf::DecodeFunction => Command::DecodeFunction { abi_path: p(0), name: p(1), data: p(2) },
            Leaf::DecodeParams => Command::DecodeParams { types: self.vals("type"), data: p(0) },
            Leaf::DecodeLog => Command::DecodeLog {
                abi_path: p(0),
                name: p(1),
                topics: self.vals("topic"),
                data: p(2),
            },
        }
    }
}
EOF"}

