use abi::{Contract, Event, Function};
use errors::{AbiError, AppError};
use paramtype::ParamType;
use std::collections::BTreeMap;
use std::io::{Read, Write};
use token::{Token, Tokenizer};

fn load_contract(path: &str) -> Result<Contract, AppError> {
    let mut file = std::fs::File::open(path)?;
    let mut data = Vec::new();
    if let Err(e) = file.read_to_end(&mut data) {
        return Err(AbiError::SerdeJson(json::JsonError::io(&e)).into());
    }
    abi::load(&data).map_err(|e| AbiError::SerdeJson(e).into())
}

fn load_function(path: &str, name_or_signature: &str) -> Result<Function, AppError> {
    let contract = load_contract(path)?;
    match name_or_signature.find('(') {
        Some(params_start) => {
            let name = &name_or_signature[..params_start];
            let functions = contract
                .functions
                .get(name)
                .ok_or_else(|| AbiError::InvalidName(name.to_owned()))?;
            functions
                .iter()
                .find(|f| f.signature() == name_or_signature)
                .cloned()
                .ok_or_else(|| AppError::msg(format!("invalid function signature `{}`", name_or_signature)))
        }
        None => {
            let functions = contract
                .functions
                .get(name_or_signature)
                .ok_or_else(|| AbiError::InvalidName(name_or_signature.to_owned()))?;
            match functions.len() {
                1 => Ok(functions[0].clone()),
                _ => Err(AppError::msg(format!(
                    "More than one function found for name `{}`, try providing the full signature",
                    name_or_signature
                ))),
            }
        }
    }
}

fn load_event(path: &str, name_or_signature: &str) -> Result<Event, AppError> {
    let contract = load_contract(path)?;
    match name_or_signature.find('(') {
        Some(params_start) => {
            let name = &name_or_signature[..params_start];
            let signature = abi::hash_signature(name_or_signature);
            let events = contract
                .events
                .get(name)
                .ok_or_else(|| AbiError::InvalidName(name.to_owned()))?;
            events
                .iter()
                .find(|e| e.signature() == signature)
                .cloned()
                .ok_or_else(|| AppError::msg(format!("Invalid signature `{}`", hexutil::h256_short(&signature))))
        }
        None => {
            let events = contract
                .events
                .get(name_or_signature)
                .ok_or_else(|| AbiError::InvalidName(name_or_signature.to_owned()))?;
            match events.len() {
                1 => Ok(events[0].clone()),
                _ => Err(AppError::msg(format!(
                    "More than one function found for name `{}`, try providing the full signature",
                    name_or_signature
                ))),
            }
        }
    }
}

fn parse_tokens(params: &[(ParamType, &str)], lenient: bool) -> Result<Vec<Token>, AppError> {
    let t = Tokenizer { lenient };
    let mut out = Vec::with_capacity(params.len());
    for (p, v) in params {
        out.push(t.tokenize(p, v)?);
    }
    Ok(out)
}

fn encode_input(path: &str, name: &str, values: &[String], lenient: bool) -> Result<String, AppError> {
    let function = load_function(path, name)?;
    let params: Vec<(ParamType, &str)> =
        function.inputs.iter().map(|p| p.kind.clone()).zip(values.iter().map(|v| v.as_str())).collect();
    let tokens = parse_tokens(&params, lenient)?;
    let types: Vec<ParamType> = function.inputs.iter().map(|p| p.kind.clone()).collect();
    if !Token::types_check(&tokens, &types) {
        return Err(AbiError::InvalidData.into());
    }
    let mut out = function.short_signature().to_vec();
    out.extend(codec::encode(&tokens));
    Ok(hexutil::encode(&out))
}

fn encode_params(params: &[String], lenient: bool) -> Result<String, AppError> {
    let mut pairs: Vec<(ParamType, &str)> = Vec::new();
    for chunk in params.chunks(2) {
        if chunk.len() < 2 {
            break;
        }
        let ty = paramtype::read(&chunk[0])?;
        pairs.push((ty, chunk[1].as_str()));
    }
    let tokens = parse_tokens(&pairs, lenient)?;
    Ok(hexutil::encode(&codec::encode(&tokens)))
}

fn decode_call_output(path: &str, name: &str, data: &str) -> Result<String, AppError> {
    let function = load_function(path, name)?;
    let data = hexutil::decode(data)?;
    let types: Vec<ParamType> = function.outputs.iter().map(|p| p.kind.clone()).collect();
    let tokens = codec::decode(&types, &data)?;
    let lines: Vec<String> = types.iter().zip(tokens.iter()).map(|(ty, to)| format!("{} {}", ty, to)).collect();
    Ok(lines.join("\n"))
}

fn decode_params(types: &[String], data: &str) -> Result<String, AppError> {
    let mut tys = Vec::with_capacity(types.len());
    for t in types {
        tys.push(paramtype::read(t)?);
    }
    let data = hexutil::decode(data)?;
    let tokens = codec::decode(&tys, &data)?;
    let lines: Vec<String> = tys.iter().zip(tokens.iter()).map(|(ty, to)| format!("{} {}", ty, to)).collect();
    Ok(lines.join("\n"))
}

fn convert_topic_param_type(kind: &ParamType) -> ParamType {
    match kind {
        ParamType::String
        | ParamType::Bytes
        | ParamType::Array(_)
        | ParamType::FixedArray(_, _)
        | ParamType::Tuple(_) => ParamType::FixedBytes(32),
        _ => kind.clone(),
    }
}

fn parse_log(event: &Event, topics: Vec<[u8; 32]>, data: Vec<u8>) -> Result<Vec<(String, Token)>, AbiError> {
    let topics_len = topics.len();
    let topic_params: Vec<&abi::EventParam> = event.inputs.iter().filter(|p| p.indexed).collect();
    let data_params: Vec<&abi::EventParam> = event.inputs.iter().filter(|p| !p.indexed).collect();
    let to_skip = if event.anonymous {
        0
    } else {
        let sig = topics.first().ok_or(AbiError::InvalidData)?;
        if *sig != event.signature() {
            return Err(AbiError::InvalidData);
        }
        1
    };
    let topic_types: Vec<ParamType> = topic_params.iter().map(|p| convert_topic_param_type(&p.kind)).collect();
    let flat_topics: Vec<u8> = topics.into_iter().skip(to_skip).flat_map(|t| t.to_vec()).collect();
    let topic_tokens = codec::decode(&topic_types, &flat_topics)?;
    if topic_tokens.len() != topics_len - to_skip {
        return Err(AbiError::InvalidData);
    }
    let mut named: BTreeMap<String, Token> = BTreeMap::new();
    for (p, t) in topic_params.iter().zip(topic_tokens.into_iter()) {
        named.insert(p.name.clone(), t);
    }
    let data_types: Vec<ParamType> = data_params.iter().map(|p| p.kind.clone()).collect();
    let data_tokens = codec::decode(&data_types, &data)?;
    for (p, t) in data_params.iter().zip(data_tokens.into_iter()) {
        named.insert(p.name.clone(), t);
    }
    Ok(event.inputs.iter().map(|p| (p.name.clone(), named[&p.name].clone())).collect())
}

fn decode_log(path: &str, name: &str, topics: &[String], data: &str) -> Result<String, AppError> {
    let event = load_event(path, name)?;
    let mut hashes = Vec::with_capacity(topics.len());
    for t in topics {
        hashes.push(hexutil::parse_h256(t)?);
    }
    let data = hexutil::decode(data)?;
    let decoded = parse_log(&event, hashes, data)?;
    let lines: Vec<String> = decoded.iter().map(|(n, v)| format!("{} {}", n, v)).collect();
    Ok(lines.join("\n"))
}

fn execute(cmd: cli::Command) -> Result<String, AppError> {
    match cmd {
        cli::Command::EncodeFunction { abi_path, name, params, lenient } => {
            encode_input(&abi_path, &name, &params, lenient)
        }
        cli::Command::EncodeParams { params, lenient } => encode_params(&params, lenient),
        cli::Command::DecodeFunction { abi_path, name, data } => decode_call_output(&abi_path, &name, &data),
        cli::Command::DecodeParams { types, data } => decode_params(&types, &data),
        cli::Command::DecodeLog { abi_path, name, topics, data } => decode_log(&abi_path, &name, &topics, &data),
